Based on \eqref{gCCS}, we assume that the center of the SIRS is at the origin of the local CCS, i.e., ${\mathbf{p}}_{\mathrm{I}}^{\mathrm{L}} = {{\mathbf{Q}}^T}\left( {\bm{\varphi}} \right)\left( {{{\mathbf{p}}_{\mathrm{I}}} - {{\mathbf{p}}_{\mathrm{I}}}} \right) = {\left[ {0,0,0} \right]^T}$, and then the coordinates of the BS, SIRS, target, and user $k$ in the local CCS are given by	
\begin{align}
	\label{lCCS}
	{\mathbf{p}}_{\mathrm{B}}^{\mathrm{L}} = {{\mathbf{Q}}^T}\left( {\bm{\varphi }} \right)\left( {{{\mathbf{p}}_{\mathrm{B}}} - {{\mathbf{p}}_{\mathrm{I}}}} \right) = {\left[ {x_{\mathrm{B}}^{\mathrm{L}},y_{\mathrm{B}}^{\mathrm{L}},z_{\mathrm{B}}^{\mathrm{L}}} \right]^T}, 
	{\mathbf{p}}_{\mathrm{T}}^{\mathrm{L}} = {{\mathbf{Q}}^T}\left( {\bm{\varphi }} \right)\left( {{{\mathbf{p}}_{\mathrm{T}}} - {{\mathbf{p}}_{\mathrm{I}}}} \right) = {\left[ {x_{\mathrm{T}}^{\mathrm{L}},y_{\mathrm{T}}^{\mathrm{L}},z_{\mathrm{T}}^{\mathrm{L}}} \right]^T}, 
	{\mathbf{p}}_k^{\mathrm{L}} = {{\mathbf{Q}}^T}\left( {\bm{\varphi }} \right)\left( {{{\mathbf{p}}_k} - {{\mathbf{p}}_{\mathrm{I}}}} \right) = {\left[ {x_k^{\mathrm{L}},y_k^{\mathrm{L}},z_k^{\mathrm{L}}} \right]^T}.
\end{align}
Based on \eqref{lCCS}, the angle of departure (AoD) from the BS to the SIRS, the angle of arrival (AoA) at the SIRS from the BS, the AoD from the SIRS to user $k$, and the AoD from the SIRS to target, the AOA from target to the SIRS sensors are given by
\begin{align}
	& {\theta _{{\mathrm{BI}}}} = \arccos \frac{{{z_{\mathrm{I}}}}}{{\left\| {{{\mathbf{p}}_{\mathrm{I}}}} \right\|}}, \vartheta _{{\mathrm{IB}}} = \arccos \frac{{ - z_{\mathrm{B}}^{\mathrm{L}}}}{{\left\| {{{\mathbf{p}}_{\mathrm{I}}}} \right\|}}, 
	& \theta _{\mathrm{I},k} \!=\! \arccos \frac{{z_k^{\mathrm{L}}}}{{\left\| {{{\mathbf{p}}_k} \!-\! {{\mathbf{p}}_{\mathrm{I}}}} \right\|}}, \theta _{{\mathrm{IT}}} = \vartheta_\mathrm{TI} \!=\! \arccos \frac{{z_{\mathrm{T}}^{\mathrm{L}}}}{{\left\| {{{\mathbf{p}}_{\mathrm{T}}} \!-\! {{\mathbf{p}}_{\mathrm{I}}}} \right\|}}.
\end{align}
The incident angle of the signal transmitted by the BS at the SIRS, the reflection angle w.r.t. user $k \in \mathcal{K}$, and the reflection angle w.r.t. the target are given by
\begin{align}
	{\theta _{\mathrm{I}}} =& \arccos \frac{{ - z_{\mathrm{B}}^{\mathrm{L}}}}{{\left\| {{{\mathbf{p}}_{\mathrm{I}}}} \right\|}},
	{\theta _k^\mathrm{r}} =& \arccos \frac{{ - z_k^{\mathrm{L}}}}{{\left\| {{{\mathbf{p}}_k} - {{\mathbf{p}}_{\mathrm{I}}}} \right\|}},
	{\theta _{\mathrm{T}}^\mathrm{r}} =& \arccos \frac{{ - z_{\mathrm{T}}^{\mathrm{L}}}}{{\left\| {{{\mathbf{p}}_{\mathrm{T}}} - {{\mathbf{p}}_{\mathrm{I}}}} \right\|}}.
\end{align}
To ensure that all users, the target, and the BS are located in the reflection space of the SIRS, we assume that ${\theta _{\mathrm{I}}} \in \left[0,\pi/2\right]$, ${\theta _k} \in \left[0,\pi/2\right]$, $k \in \mathcal{K}$, and ${\theta _{\mathrm{T}}} \in \left[0,\pi/2\right]$. Then, it follows that
\begin{align}
	\cos {\theta _{\mathrm{I}}} =& \frac{{ x_\mathrm{I} q_3  + y_\mathrm{I} q_6 + z_\mathrm{I} q_9 }}{{\sqrt {x_{\mathrm{I}}^2 + y_{\mathrm{I}}^2 + z_{\mathrm{I}}^2} }}, \label{theta_i}
	\cos {\theta _k^\mathrm{r}} =& \frac{{ ( {{x_{\mathrm{I}}} - {x_k}} )q_3  +  ( {{y_{\mathrm{I}}} - {y_k}} )q_6 +  ( {{z_{\mathrm{I}}} - {z_k}} ) q_9 }}{{\sqrt {{{\left( {{x_{\mathrm{I}}} - {x_k}} \right)}^2} + {{\left( {{y_{\mathrm{I}}} - {y_k}} \right)}^2} + {{\left( {{z_{\mathrm{I}}} - {z_k}} \right)}^2} } }},
	\cos {\theta _{\mathrm{T}}^\mathrm{r}} =& \frac{{\left( {{x_{\mathrm{I}}} - {x_{\mathrm{T}}}} \right)q_3 + \left( {{y_{\mathrm{I}}} - {y_{\mathrm{T}}}} \right)q_6 + \left( {{z_{\mathrm{I}}} - {z_{\mathrm{T}}}} \right)q_9 }}{{\sqrt {{{\left( {{x_{\mathrm{I}}} - {x_{\mathrm{T}}}} \right)}^2} + {{\left( {{y_{\mathrm{I}}} - {y_{\mathrm{T}}}} \right)}^2} + {{\left( {{z_{\mathrm{I}}} - {z_{\mathrm{T}}}} \right)}^2}} }}. \label{vartheta_TI}
\end{align}
As such, the effective aperture gain due to the SIRS’s orientation w.r.t. user $k$ and target can be expressed as
\begin{align}
	{F_k}\left( \bm{\varphi}  \right) = \cos {\theta _{\mathrm{I}}}\cos {\theta _k^{\mathrm{r}}},
		{F_{\mathrm{T}}}\left( \bm{\varphi}  \right) = \cos {\theta _{\mathrm{I}}}\cos {\theta _{\mathrm{T}}^{\mathrm{r}}}.
\end{align}
We consider an ISAC transmission block consisting of $T$ symbols, and the set of symbols is represented as $\mathcal{T} = \{1, \cdots , T\}$. The transmit signal at the BS is given by
\begin{align}
	{\mathbf{x}}\left( t \right) = \sum _{k \in \mathcal{K}}\mathbf{w}_{k}\mathbf{c}_{k}\left( t \right) + {\mathbf{s}}\left( t \right), t \in \mathcal{T},
\end{align}
where ${\mathbf{c}}(t) = \left[\mathbf{c}_{1}\left( t \right),\cdots,\mathbf{c}_{K}\left( t \right)\right]^T$ denotes the communication signal for users satisfying ${\mathbf{c}}\left( t \right) \sim \mathcal{CN}\left( {{\mathbf{0}},{{\mathbf{I}}_K}} \right)$, and ${\mathbf{s}}(t) \in \mathbb{C}^{M \times 1}$ represents the sensing signal with zero mean and covariance ${{\mathbf{R}}_{\mathrm{s}}} = \frac{1}{T}\sum\limits_{t = 1}^T {{\mathbf{s}}\left( t \right){{\mathbf{s}}^H}\left( t \right)} \succeq 0$. Assume that communication signals and sensing signals are statistically independent, the covariance matrix of the transmit signal is given by
\begin{align}
	{{\mathbf{R}}_{\mathrm{x}}} \!=\! \frac{1}{T}\sum\limits_{t = 1}^T {{\mathbf{x}}( t ){{\mathbf{x}}^H}( t )}  \approx \mathbb{E}\{ {{\mathbf{x}}\left( t \right){{\mathbf{x}}^H}( t )} \} \!=\! \sum _{k \in \mathcal{K}}\mathbf{W}_{k} \!+\! {{\mathbf{R}}_{\mathrm{s}}},
\end{align}
where $\mathbf{W}_{k} = \mathbf{w}_{k}\mathbf{w}_{k}^H$ with $\mathbf{W}_{k} \succeq 0$ and $\operatorname{rank} \left(\mathbf{W}_{k}\right) = 1$.

To facilitate the channel description, the steering vector function is defined as
\begin{align}
	{\mathbf{u}}\left( {\bar \theta ,\bar N} \right) = \left[ {{e^{ - \frac{{\jmath \pi \left( {\bar N - 1} \right)\bar \theta }}{2}}},{e^{ - \frac{{\jmath \pi \left( {\bar N - 3} \right)\bar \theta }}{2}}}, \cdots ,{e^{\frac{{\jmath \pi \left( {\bar N - 1} \right)\bar \theta }}{2}}}} \right],
\end{align}
where $\bar \theta$ denotes the phase difference between the observations at two adjacent elements and $\bar N$ is assumed as an even number denoting the size of an uniform linear array (ULA).

We assume far-field and quasi-static scenarios. The locations of the scatterers are assumed to be known a priori and remain fixed within each coherence block, which can be obtained from geometric priors or offline estimation. Let $C$ denote the number of scatterers. The coordinates of the $c$-th scatterer in the global CCS and local CCS are given by $\mathbf{p}_c = [x_c,y_c,z_c]^T$ and $\mathbf{p}_c^\mathrm{L} = [x_c^\mathrm{L},y_c^\mathrm{L},z_c^\mathrm{L}]^T$, $c \in \mathcal{C} = \{1, \cdots, C\}$, respectively. The BS-SIRS channel is modeled as
\begin{align}
 \label{path}
	{{\mathbf{H}}_{{\mathrm{BI}}}} = \sqrt{\frac{1}{C+1}} ({\bar {\mathbf{H}}_{{\mathrm{BI}}}} +  \sum\limits_{c = 1}^C {{{\tilde \alpha }_c}{{\bf{a}}_{{\rm{IB}}}}\left( {{\vartheta _c}} \right){\bf{a}}_{{\rm{BI}}}^T\left( {{\theta _c}} \right)} ),
\end{align}
where ${{\mathbf{a}}_{{\mathrm{IB}}}}\left( {\vartheta _{c}} \right) = {\mathbf{u}}\left( {\frac{{2{d_{\mathrm{I}}}}}{\lambda }\sin \vartheta _{c},N} \right)$, ${{\mathbf{a}}_{{\mathrm{BI}}}}\left( {{\theta _{c}}} \right) = {\mathbf{u}}\left( {\frac{{2{d_{\mathrm{B}}}}}{\lambda }\sin {\theta _{c}},M} \right)$ with ${\theta _c} = \arccos \frac{{{z_c}}}{{\left\| {{{\mathbf{p}}_c}} \right\|}}$ and $\vartheta _c = \arccos \frac{{ z_c^{\mathrm{L}}}}{{\left\| {{{\mathbf{p}}_c}} - {{{\mathbf{p}}_{\mathrm{I}}}} \right\|}}$, as well as ${{\tilde \alpha }_c} = \frac{\lambda^2}{(4\pi)^2 d_{\mathrm{B},c} d_{\mathrm{I},c}}
e^{-j\frac{2\pi}{\lambda}(d_{\mathrm{B},c} + d_{\mathrm{I},c})}$ denotes the path loss of the $c$-th path with $d_{\mathrm{B},c} = \|\mathbf{p}_c - \mathbf{p}_\mathrm{B}\|$ and $d_{\mathrm{I},c} = \|\mathbf{p}_\mathrm{I} - \mathbf{p}_c\|$. The SIRS elements spacing and the BS antenna spacing are denoted by $d_{\mathrm{I}}$ and $d_{\mathrm{B}}$, respectively, and $\lambda$ is the wavelength. The LoS-dominant path is given by
\begin{align}
	{\bar {\mathbf{H}}_{{\mathrm{BI}}}} = {\tilde {\alpha} _{{0}}}{{\mathbf{a}}_{{\mathrm{IB}}}}\left( \vartheta _{{\mathrm{IB}}} \right){\mathbf{a}}_{{\mathrm{BI}}}^T\left( {{\theta _{{\mathrm{BI}}}}} \right),
\end{align}
where ${\tilde {\alpha} _{{0}}} = \sqrt {\frac{{{\lambda ^2}}}{{16{\pi ^2}d_{{\mathrm{BI}}}^2}}} {e^{ - \jmath \frac{{2\pi {d_{{\mathrm{BI}}}}}}{\lambda }}}$ with $d_\mathrm{BI} = \|\mathbf{p}_\mathrm{B} - \mathbf{p}_\mathrm{I}\|$, ${{\mathbf{a}}_{{\mathrm{IB}}}}\left( {\vartheta _{{\mathrm{IB}}}} \right) = {\mathbf{u}}\left( {\frac{{2{d_{\mathrm{I}}}}}{\lambda }\sin \vartheta _{{\mathrm{IB}}},N} \right)$, and ${{\mathbf{a}}_{{\mathrm{BI}}}}\left( {{\theta _{{\mathrm{BI}}}}} \right) = {\mathbf{u}}\left( {\frac{{2{d_{\mathrm{B}}}}}{\lambda }\sin {\theta _{{\mathrm{BI}}}},M} \right)$.


\subsection{Communication Model}
The channel between SIRS and the user $k$ is modeled as
\begin{align}
	{\mathbf{h}}_{k}^H = {\alpha _k}{\mathbf{a}}_{k}^T\left( \theta _{\mathrm{I},k} \right),
\end{align}	
where ${\alpha _k} = \sqrt {\frac{{{\lambda ^2}}}{{16{\pi ^2}d_k^2}}} {e^{ - \jmath \frac{{2\pi {d_k}}}{\lambda }}}$ with $d_k = \|\mathbf{p}_k - \mathbf{p}_\mathrm{I}\|$, and ${{\mathbf{a}}_k}\left( \theta _{\mathrm{I},k} \right) = {\mathbf{u}}\left( {\frac{{2{d_{\mathrm{I}}}}}{\lambda }\sin \theta _{\mathrm{I},k},{N}} \right) $.


The signal received at the user $k$ is given by
\begin{align}
	{y_k}\left(t\right) = \sqrt{{F_k}\left( {\bm{\varphi }} \right)} {\mathbf{h}}_k^H{\mathbf{\Phi }}{{\mathbf{H}}_{{\mathrm{BI}}}}{\mathbf{x}}\left( t \right) + {n_k}\left(t\right),
\end{align}
where ${\mathbf{\Phi}} = \operatorname{diag}\left(e^{j\phi_1},\cdots,e^{j\phi_N} \right)$ denotes the reflection matrix of the SIRS and ${n_k}\left(t\right) \sim \mathcal{CN} \left(0, \sigma_k^2\right)$ denotes the additive white Gaussian noise (AWGN) at $k$-th user. We consider the user receivers are dedicated designed for ISAC, which can cancel the interference from the sensing signal. As such, the received SINR of user $k$ is given by
\begin{align}
	{\gamma _k} (\bm{\varphi}, \mathbf{W}_{k},\mathbf{\Phi} ) \!=\! \frac{{{F_k}\left( {\bm{\varphi }} \right)}{{{ {{\mathbf{h}}_{k}^H{\mathbf{\Phi }}{{\mathbf{H}}_{{\mathrm{BI}}}}{{\mathbf{W}}_k}}{\mathbf{H}}_{{\mathrm{BI}}}^H \mathbf{\Phi }^H {\mathbf{h}}_{k}}}}}{{\sum \limits_{i \in \mathcal{K}, i \ne k} \!\!\!\!\! {{F_k}\left( {\bm{\varphi }} \right)}{ {{{ {{\mathbf{h}}_{k}^H{\mathbf{\Phi }}{{\mathbf{H}}_{{\mathrm{BI}}}}{{\mathbf{W}}_i}}{\mathbf{H}}_{{\mathrm{BI}}}^H \mathbf{\Phi }^H {\mathbf{h}}_{k}}}} \!+\! \sigma _k^2} }}.
\end{align}

\subsection{Sensing Model}
The SIRS element-target-SIRS sensor channel is given by
\begin{align}
	{{\mathbf{H}}_{{\mathrm{ITI}}}} = {\alpha _{{\mathrm{ITI}}}}{{\mathbf{a}}_{{\mathrm{TI}}}}\left( {{\vartheta _{{\mathrm{TI}}}}} \right){\mathbf{a}}_{{\mathrm{IT}}}^T\left( \theta _{{\mathrm{IT}}} \right),
\end{align}
where ${\alpha _{{\mathrm{ITI}}}} = {\beta _0}{\beta _{{\mathrm{ITI}}}}$ with ${\beta _0} \sim \mathcal{CN}\left( {0,1} \right)$ and $\beta _{{\mathrm{ITI}}} = \sqrt{\frac{\lambda^2 \kappa}{64 \pi^3 d^4_\mathrm{IT}}}$, ${{\mathbf{a}}_{{\mathrm{TI}}}}\left( {{\vartheta _{{\mathrm{TI}}}}} \right) = {\mathbf{u}}\left( {\frac{{2{d_{\mathrm{S}}}}}{\lambda }\sin {\vartheta _{{\mathrm{TI}}}},L} \right)$ with the SIRS sensor spacing $d_{\mathrm{S}}$, and ${{\mathbf{a}}_{{\mathrm{IT}}}}\left( \theta _{{\mathrm{IT}}} \right) = {\mathbf{u}}\left( {\frac{{2{d_{\mathrm{I}}}}}{\lambda }\sin \theta _{{\mathrm{IT}}},{N}} \right)$. The distance between the SIRS and the target is denoted by $d_\mathrm{IT} = \|\mathbf{p}_\mathrm{T} - \mathbf{p}_\mathrm{I}\|$ and $\kappa$ represents the radar cross-section. 

It is assumed that the direct-path component from the BS to the sensor can be acquired a priori via offline estimation and perfectly canceled at the sensor before target's spatial-frequency estimation. Thus, the received echo signal at time symbol $t$ is given by 
\begin{align}
	\mathbf{y}_{\mathrm{s}}(t) = \sqrt{F_\mathrm{T}(\bm{\varphi})} {{\mathbf{H}}_{{\mathrm{ITI}}}} \mathbf{\Phi} {{\mathbf{H}}_{{\mathrm{BI}}}} \mathbf{x} (t) +  \mathbf{n}_{\mathrm{T}} (t),
\end{align}
where $\mathbf{n}_{\mathrm{T}} (t) \sim \mathcal{CN} \left(0, \sigma _\mathrm{T}^2 \mathbf{I}_{L} \right)$ denotes the received noise at the SIRS sensors.

Let $\bar \vartheta _{{\mathrm{TI}}} = \sin \vartheta _{{\mathrm{TI}}} = \sin \theta _ {\mathrm{IT}}$ and ${\mathbf{A}} = {{\mathbf{a}}_{{\mathrm{TI}}}}( \bar \vartheta _{{\mathrm{TI}}} ){\mathbf{a}}_{{\mathrm{IT}}}^T( \bar \vartheta _{{\mathrm{TI}}} ) \mathbf{\Phi} {{\mathbf{H}}_{{\mathrm{BI}}}} $. The CRB of the estimated $\bar \vartheta _{{\mathrm{TI}}}$ is given by
\begin{align}
	\operatorname{CRB}{\!( \bar \vartheta _{{\mathrm{TI}}} \!)} \!=\! \frac{{\sigma _{\mathrm{T}}^2}}{{2T{{| {{\alpha _{{\mathrm{ITI}}}}} |}^2} {F_\mathrm{T}(\bm{\varphi})} ( {\operatorname{tr} ( {{\mathbf{\dot{A}}}{{\mathbf{R}}_{\mathrm{x}}}{{{\mathbf{\dot{A}}}}^H}} ) \!-\! \frac{{{{| {\operatorname{tr} ( {{\mathbf{A}}{{\mathbf{R}}_{\mathrm{x}}}{{{\mathbf{\dot{A}}}}^H}} )} |}^2}}}{{\operatorname{tr} ( {{\mathbf{A}}{{\mathbf{R}}_{\mathrm{x}}}{{\mathbf{A}}^H}} )}}} )}}.
\end{align}
Assuming that the inter-element distance and the inter-sensor distance are the same, i.e., $d_\mathrm{s} = d_\mathrm{I} = \bar d$, the derivative of ${{\mathbf{a}}_{{\mathrm{TI}}}}\left( \bar \vartheta _{{\mathrm{TI}}} \right)$ and ${{\mathbf{a}}_{{\mathrm{IT}}}}\left( \bar \vartheta _{{\mathrm{TI}}} \right)$ are given by 
\begin{align}
	{{\mathbf{\dot a}}_{{\mathrm{TI}}}}\left( \bar \vartheta _{{\mathrm{TI}}} \right) &= \frac{{\partial {{\mathbf{ a}}_{{\mathrm{TI}}}}\left( \bar \vartheta _{{\mathrm{TI}}} \right)}}{{\partial \bar \vartheta _{{\mathrm{TI}}}}}= j \pi \frac{\bar d}{\lambda}{{\mathbf{D}}_{\mathrm{TI}}} {{\mathbf{ a}}_{{\mathrm{TI}}}}\left( \bar \vartheta _{{\mathrm{TI}}} \right), \label{adot}
	{{\mathbf{\dot a}}_{{\mathrm{IT}}}}\left( \bar \vartheta _{{\mathrm{TI}}} \right) &= \frac{{\partial {{\mathbf{ a}}_{{\mathrm{IT}}}}\left( \bar \vartheta _{{\mathrm{TI}}} \right)}}{{\partial \bar \vartheta _{{\mathrm{TI}}} }} = j \pi \frac{\bar d}{\lambda}{{\mathbf{D}}_{\mathrm{IT}}}{{\mathbf{ a}}_{{\mathrm{IT}}}}\left( \bar \vartheta _{{\mathrm{TI}}} \right), \label{bdot}
\end{align}
with ${{\mathbf{D}}_{\mathrm{TI}}} = {\operatorname{diag}} ( { - ( {L - 1} ), - ( {L - 3} ), \ldots , ( {L - 1} )} )$ and ${{\mathbf{D}}_{\mathrm{IT}}} = {\operatorname{diag}} ( { - ( {N - 1} ), - ( {N - 3} ), \ldots , ( {N - 1} )} )$. Let $\mathbf v=[e^{j\phi_1},\ldots,e^{j\phi_N}]^T$ denote the IRS reflection coefficient vector, such that $\bm\Phi=\operatorname{diag}(\mathbf v)$ and $|v_n|=1$, $\forall n\in\mathcal N$. By introducing ${\mathbf{B}} = \operatorname{diag} \left({\mathbf{a}}_{{\mathrm{IT}}}\left( \bar \vartheta _{{\mathrm{TI}}} \right)\right)$, we have 
\begin{align}
	&{\mathbf{A}} = {{\mathbf{a}}_{{\mathrm{TI}}}}( \bar \vartheta _{{\mathrm{TI}}} ){\mathbf{a}}_{{\mathrm{IT}}}^T( \bar \vartheta _{{\mathrm{TI}}} ) \mathbf{\Phi} {{\mathbf{H}}_{{\mathrm{BI}}}}  = {{\mathbf{a}}_{{\mathrm{TI}}}}( \bar \vartheta _{{\mathrm{TI}}} ) \mathbf{v}^T \mathbf{B} {{\mathbf{H}}_{{\mathrm{BI}}}}, \label{A}
	&\mathbf{\dot A} = {{\mathbf{\dot a}}_{{\mathrm{TI}}}}( \bar \vartheta _{{\mathrm{TI}}} ){\mathbf{a}}_{{\mathrm{IT}}}^T( \bar \vartheta _{{\mathrm{TI}}} ) \mathbf{\Phi} {{\mathbf{H}}_{{\mathrm{BI}}}} + {{\mathbf{a}}_{{\mathrm{TI}}}}( \bar \vartheta _{{\mathrm{TI}}} ){\mathbf{\dot a}}_{{\mathrm{IT}}}^T( \bar \vartheta _{{\mathrm{TI}}} ) \mathbf{\Phi} {{\mathbf{H}}_{{\mathrm{BI}}}} \nonumber
	&= j \pi \frac{{{\bar d}}}{{{\lambda}}} ({{\mathbf{D}}_{\mathrm{TI}}} {{\mathbf{a}}_{{\mathrm{TI}}}}( \bar \vartheta _{{\mathrm{TI}}} ) \mathbf{v}^T \mathbf{B} {{\mathbf{H}}_{{\mathrm{BI}}}} + {{\mathbf{a}}_{{\mathrm{TI}}}}{{\mathbf{v}}^T}{\mathbf{D}_\mathrm{IT}}{\mathbf{B {{\mathbf{H}}_{{\mathrm{BI}}}}}}). \label{Adot}
\end{align}
Based on \eqref{adot}, \eqref{bdot}, \eqref{A} and \eqref{Adot}, it yields
\begin{align}
	{\operatorname{tr}} ( {{\mathbf{A}}{{\mathbf{R}}_{\mathrm{x}}}{{\mathbf{A}}^H}} ) 
	= & L {{{\mathbf{v}}^H}{{\mathbf{R}}_1}{\mathbf{v}}}, \label{BB} 
	{\operatorname{tr}} ( {{\mathbf{A}}{{\mathbf{R}}_{\mathrm{x}}}{{{\mathbf{\dot A}}}^H}} )
	= & -j \pi \frac{{{\bar d}}}{{{\lambda}}} L {{{\mathbf{v}}^H}{\mathbf{D}_\mathrm{IT}}{{\mathbf{R}}_1}{\mathbf{v}}}, \label{BBdot} 
	{\operatorname{tr}} ( {{\mathbf{\dot A}}{{\mathbf{R}}_{\mathrm{x}}}{{{\mathbf{\dot A}}}^H}} ) 
	=&  {\pi ^2}\frac{{{\bar d}^2}}{{\lambda ^2}} \frac{L^3-L}{3} {{{\mathbf{v}}^H}{{\mathbf{R}}_1}{\mathbf{v}}} \nonumber
	&+ {\pi ^2}\frac{{{\bar d}^2}}{{\lambda ^2}} L {{{\mathbf{v}}^H}{\mathbf{D}_\mathrm{IT}}{{\mathbf{R}}_1}{\mathbf{D}_\mathrm{IT}}{\mathbf{v}}}, \label{BdotBdot}
