\section{Problem Formulation and Solutions}
In this section, we first formulate a joint optimization problem to minimize the CRB for target's spatial-frequency estimation while satisfying the SINR threshold of the communication users. Then, we analyze special cases to characterize the impact of SIRS rotation on the effective aperture gains and channel correlation, which provides useful insights and lays the foundation for the general multi-user case.
Based on the derived CRB and the angle-dependent model, we aim to minimize the CRB for target's spatial-frequency estimation by jointly optimizing the BS beamforming, the SIRS beamforming, and the rotation angles. Thus, the SINR-constrained CRB minimization problem is formulated as
\begin{subequations}
	\label{pro:original}
	\begin{align}
		\mathop {\min }\limits_{\substack{\mathbf{\Phi}, \{\mathbf{W}_{k}\},  \mathbf{R}_\mathrm{s}, \bm{\varphi}}} &\operatorname{CRB}{\left( \bar \vartheta _{{\mathrm{TI}}} \right)} 
		\mathrm{s.t.} \;\;\; & {\gamma _k} \left(\bm{\varphi}, \mathbf{W}_{k},\mathbf{\Phi} \right) \ge \Gamma_k, \forall k \in \mathcal{K}, \label{sinr}
		& \sum_{k \in \mathcal{K}}\operatorname{tr}\left(\mathbf{W}_{k}\right) + \operatorname{tr}\left(\mathbf{R}_\mathrm{s}\right) \le P_0, \label{txpower}
		& \mathbf{R}_\mathrm{s} \succeq 0, \label{Rs} 
		&\mathbf{W}_{k} \succeq 0, \forall k \in \mathcal{K}, \label{wk}
		& \operatorname{rank} (\mathbf{W}_{k}) = 1, \forall k \in \mathcal{K}, \label{rankwk} 
		& {x_{\mathrm{I}}}{q_3} \!+\! {y_{\mathrm{I}}}{q_6} \!+\! {z_{\mathrm{I}}}{q_9} \ge 0, \label{BSrotation}
		& ( {{x_{\mathrm{I}}} \!-\! {x_{\mathrm{T}}}} ){q_3} + ( {{y_{\mathrm{I}}} \!-\! {y_{\mathrm{T}}}} ){q_6} \!+\! ( {{z_{\mathrm{I}}} \!- \! {z_{\mathrm{T}}}} ){q_9} \ge 0, \label{targetrotation}
		& ( {{x_{\mathrm{I}}} \!-\! {x_k}} ){q_3} \!+\! ( {{y_{\mathrm{I}}} \!-\! {y_k}} ){q_6} \!+\! ( {{z_{\mathrm{I}}} \!-\! {z_k}} ){q_9} \ge 0, \forall k \in \mathcal{K}, \label{userrotation} 
		&|{\mathbf{\Phi}}_{n,n}|=1, \forall n \in \mathcal{N}, \label{rank1}
	\end{align}
\end{subequations}
where $P_0$ denote the maximum tansmit power at the BS, $\Gamma_k, \forall k \in \mathcal{K}$ represents the pre-defined communication SINR threshold w.r.t. user $k$. For problem \eqref{pro:original}, constraints \eqref{sinr} and \eqref{txpower} are the per-user SINR requirement and the maximum power budget, respectively, while constraints \eqref{Rs} and \eqref{wk} are the positive semidefinite constraints on the optimization variables. Constraint \eqref{rankwk} imposes the rank-one condition. Constraints \eqref{BSrotation}–\eqref{userrotation} ensure that the BS, the target, and all users lie in the reflection half-space of the SIRS. Constraint \eqref{rank1} is the unit-modulus constraint on each IRS phase shift. Due to the coupling between the rotation-dependent aperture gains, the BS beamformer, and the IRS beamformer, problem \eqref{pro:original} is non-convex and thus challenging to solve.

In the following, we discuss special cases under the BS–SIRS channel model with only a LoS-dominant path. Specifically, for the sensing-only and communication-only cases, the CRB for estimating $\bar \vartheta_{\mathrm{TI}}$ and the communication SNR are minimized and maximized, respectively. We then consider a co-located user and target case to determine the feasibility condition imposed by the communication requirement. In the case with a separated user and target, we design the SIRS rotation to improve the correlation between communication and sensing. For clarity, we denote the user index as U. 

\subsection{Sensing-Only Case}
We first consider the special case of target sensing, and then we have ${\mathbf{A}} = {\tilde {\alpha} _{{0}}} {{\mathbf{a}}_{{\mathrm{TI}}}}{\left( {{\bar \vartheta _{{\mathrm{TI}}}}} \right)}{\mathbf{a}}_{{\mathrm{IT}}}^T{\left( {{\bar \vartheta _{{\mathrm{TI}}}}} \right)}{\mathbf{\Phi }}{{\mathbf{a}}_{{\mathrm{IB}}}}\left( {{\vartheta _{{\mathrm{IB}}}}} \right){\mathbf{a}}_{{\mathrm{BI}}}^T\left( {{\theta _{{\mathrm{BI}}}}} \right)$ and $\mathbf{\dot A} = {\tilde {\alpha} _{{0}}} {{\mathbf{\dot a}}_{{\mathrm{TI}}}}( \bar \vartheta _{{\mathrm{TI}}} ){\mathbf{a}}_{{\mathrm{IT}}}^T( \bar \vartheta _{{\mathrm{TI}}} ) \mathbf{\Phi} {{\mathbf{a}}_{{\mathrm{IB}}}}\left( {{\vartheta _{{\mathrm{IB}}}}} \right){\mathbf{a}}_{{\mathrm{BI}}}^T\left( {{\theta _{{\mathrm{BI}}}}} \right) +{\tilde {\alpha} _{{0}}} {{\mathbf{a}}_{{\mathrm{TI}}}}( \bar \vartheta _{{\mathrm{TI}}} ){\mathbf{\dot a}}_{{\mathrm{IT}}}^T( \bar \vartheta _{{\mathrm{TI}}} ) \mathbf{\Phi} {{\mathbf{a}}_{{\mathrm{IB}}}}\left( {{\vartheta _{{\mathrm{IB}}}}} \right){\mathbf{a}}_{{\mathrm{BI}}}^T\left( {{\theta _{{\mathrm{BI}}}}} \right)$, which yields
\begin{align}
	&\operatorname{tr} ( {{\mathbf{A}}{{\mathbf{R}}_{\mathrm{x}}}{{\mathbf{A}}^H}} ) = {|\alpha _{{\mathrm{BI}}}|^2}{\left\| {{{\mathbf{a}}_{{\mathrm{TI}}}}{\left( {{\bar \vartheta _{{\mathrm{TI}}}}} \right)}} \right\|^2}{\left| {{\mathbf{a}}_{{\mathrm{IT}}}^T{\left( {{\bar \vartheta _{{\mathrm{TI}}}}} \right)}{\mathbf{\Phi }}{{\mathbf{a}}_{{\mathrm{IB}}}}\left( {{\vartheta _{{\mathrm{IB}}}}} \right)} \right|^2}\nonumber
	&\times {\mathbf{a}}_{{\mathrm{BI}}}^T\left( {{\theta _{{\mathrm{BI}}}}} \right){{\mathbf{R}}_{\mathrm{x}}}{{\mathbf{a}}_{{\mathrm{BI}}}^*}{\left( {{\theta _{{\mathrm{BI}}}}} \right)}, \label{A1} 
	&\operatorname{tr} ( {{\mathbf{A}}{{\mathbf{R}}_{\mathrm{x}}}{{{\mathbf{\dot{A}}}}^H}} ) = {|\alpha _{{\mathrm{BI}}}|^2} {\left\| {{{\mathbf{a}}_{{\mathrm{TI}}}}{\left( {{\bar \vartheta _{{\mathrm{TI}}}}} \right)}} \right\|^2}{\mathbf{a}}_{{\mathrm{IT}}}^T{\left( {{\bar \vartheta _{{\mathrm{TI}}}}} \right)}{\mathbf{\Phi }}{{\mathbf{a}}_{{\mathrm{IB}}}}\left( {{\vartheta _{{\mathrm{IB}}}}} \right)\nonumber
	&\times {\mathbf{a}}_{{\mathrm{BI}}}^T\left( {{\theta _{{\mathrm{BI}}}}} \right){{\mathbf{R}}_{\mathrm{x}}}{{\mathbf{a}}^*_{{\mathrm{BI}}}}\left( {{\theta _{{\mathrm{BI}}}}} \right) {\mathbf{a}}_{{\mathrm{IB}}}^H\left( {{\vartheta _{{\mathrm{IB}}}}} \right){{\mathbf{\Phi }}^H}{{{\mathbf{\dot a}}}^*_{{\mathrm{IT}}}}{\left( {{\bar \vartheta _{{\mathrm{TI}}}}} \right)},  \label{A2} 
	&\operatorname{tr} ( {{\mathbf{\dot{A}}}{{\mathbf{R}}_{\mathrm{x}}}{{{\mathbf{\dot{A}}}}^H}} ) = {|\alpha _{{\mathrm{BI}}}|^2} {\left\| {{{{\mathbf{\dot a}}}_{{\mathrm{TI}}}}{\left( {{\bar \vartheta _{{\mathrm{TI}}}}} \right)}} \right\|^2}{\left| {{\mathbf{a}}_{{\mathrm{IT}}}^T{\left( {{\bar \vartheta _{{\mathrm{TI}}}}} \right)}{\mathbf{\Phi }}{{\mathbf{a}}_{{\mathrm{IB}}}}\left( {{\vartheta _{{\mathrm{IB}}}}} \right)} \right|^2}\nonumber
	&\times {\mathbf{a}}_{{\mathrm{BI}}}^T\left( {{\theta _{{\mathrm{BI}}}}} \right){{\mathbf{R}}_{\mathrm{x}}}{{\mathbf{a}}^*_{{\mathrm{BI}}}}\left( {{\theta _{{\mathrm{BI}}}}} \right) + {|\alpha _{{\mathrm{BI}}}|^2} {\left\| {{{\mathbf{a}}_{{\mathrm{TI}}}}{\left( {{\bar \vartheta _{{\mathrm{TI}}}}} \right)}} \right\|^2}\nonumber
	&\times {\left| {{\mathbf{\dot a}}_{{\mathrm{IT}}}^T{\left( {{\bar \vartheta _{{\mathrm{TI}}}}} \right)}{\mathbf{\Phi }}{{\mathbf{a}}_{{\mathrm{IB}}}}\left( {{\vartheta _{{\mathrm{IB}}}}} \right)} \right|^2}{\mathbf{a}}_{{\mathrm{BI}}}^T\left( {{\theta _{{\mathrm{BI}}}}} \right){{\mathbf{R}}_{\mathrm{x}}}{{\mathbf{a}}^*_{{\mathrm{BI}}}}\left( {{\theta _{{\mathrm{BI}}}}} \right). \label{A3}
\end{align}
Then, it follows that
\begin{align}
&{| {\operatorname{tr} ( {{\mathbf{A}}{{\mathbf{R}}_{\mathrm{x}}}{{{\mathbf{\dot A}}}^H}} )} |}^2 
= |{\tilde {\alpha} _{{0}}}|^4{\| {{{\mathbf{a}}_{{\mathrm{TI}}}}( {{\bar \vartheta _{{\mathrm{TI}}}}} )} \|^4} {| {{\mathbf{\dot a}}_{{\mathrm{IT}}}^T( {{\bar \vartheta _{{\mathrm{TI}}}}} ){\mathbf{\Phi }}{{\mathbf{a}}_{{\mathrm{IB}}}}( {{\vartheta _{{\mathrm{IB}}}}} )} |^2} \nonumber 
&\times {| {{\mathbf{a}}_{{\mathrm{IT}}}^T( {{\bar \vartheta _{{\mathrm{TI}}}}} ){{\mathbf{\Phi }}}{{\mathbf{a}}_{{\mathrm{IB}}}}( {{\vartheta _{{\mathrm{IB}}}}} )} |^2} | {{\mathbf{a}}_{{\mathrm{BI}}}^T( {{\theta _{{\mathrm{BI}}}}} ){{\mathbf{R}}_{\mathrm{x}}}{{\mathbf{a}}^*_{{\mathrm{BI}}}}( {{\theta _{{\mathrm{BI}}}}} )} |^2. \label{A22}
\end{align}
Based on \eqref{A1} and \eqref{A22}, we have $\frac{{{{| {\operatorname{tr} ( {{\mathbf{A}}{{\mathbf{R}}_{\mathrm{x}}}{{{\mathbf{\dot{A}}}}^H}} )} |}^2}}}{{\operatorname{tr} ( {{\mathbf{A}}{{\mathbf{R}}_{\mathrm{x}}}{{\mathbf{A}}^H}} )}} =  {|\alpha _{{\mathrm{BI}}}|^2} {\| {{{\mathbf{a}}_{{\mathrm{TI}}}}{( {{\bar \vartheta _{{\mathrm{TI}}}}} )}} \|^2} {| {{\mathbf{\dot a}}_{{\mathrm{IT}}}^T{( {{\bar \vartheta _{{\mathrm{TI}}}}} )}{\mathbf{\Phi }}{{\mathbf{a}}_{{\mathrm{IB}}}}( {{\vartheta _{{\mathrm{IB}}}}} )} |^2}{\mathbf{a}}_{{\mathrm{BI}}}^T( {{\theta _{{\mathrm{BI}}}}} ){{\mathbf{R}}_{\mathrm{x}}}{{\mathbf{a}}^*_{{\mathrm{BI}}}}( {{\theta _{{\mathrm{BI}}}}} )$. As such, the CRB of the estimated ${{\bar \vartheta _{{\mathrm{TI}}}}}$ is expressed in \eqref{CRB_LoS}.
\begin{figure*}
	\begin{align}
		\label{CRB_LoS}
		\operatorname{CRB}{\left( {{\bar \vartheta _{{\mathrm{TI}}}}} \right)} = \frac{3 {\sigma _{\mathrm{T}}^2} \lambda ^2}{{2T{|\alpha _{{\mathrm{BI}}}|^2}{\left| {{\alpha _{{\mathrm{ITI}}}}} \right|^2} \pi^2 \bar{d}^2 (L^3 - L) {{F_{\mathrm{T}}}\left( \bm{\varphi}  \right) {\left| {{\mathbf{a}}_{{\mathrm{IT}}}^T{\left( \bar \vartheta _{{\mathrm{TI}}} \right)}{\mathbf{\Phi }}{{\mathbf{a}}_{{\mathrm{IB}}}}\left( {{\vartheta _{{\mathrm{IB}}}}} \right)} \right|^2}{\mathbf{a}}_{{\mathrm{BI}}}^T\left( {{\theta _{{\mathrm{BI}}}}} \right){{\mathbf{R}}_{\mathrm{x}}}{{\mathbf{a}}^*_{{\mathrm{BI}}}}\left( {{\theta _{{\mathrm{BI}}}}} \right)} }}.
