Based on \eqref{CRB_LoS}, problem \eqref{pro:original} is reduced to
\begin{subequations}
	\label{pro:CRB}
	\begin{align}
		\mathop {\min }\limits_{\mathbf{\Phi},\mathbf{R}_\mathrm{s},\bm{\varphi}} \; &\operatorname{CRB}{\left( \bar \vartheta _{{\mathrm{TI}}} \right)} 
		\mathrm{s.t.} \;\;\;\; 
		& \operatorname{tr}\left(\mathbf{R}_\mathrm{s}\right) \le P_0,
		& \eqref{Rs}, \eqref{BSrotation}, \eqref{targetrotation}, \eqref{rank1}.
	\end{align}
\end{subequations}

Given $\mathbf{\Phi}$ and $\bm{\varphi}$, the optimal beamforming at the BS is given by
\begin{align}
	\label{BS_BF_S}
	{\mathbf{R}}_{\mathrm{s}}^{\star} = {P_0}\frac{{{{\mathbf{a}}^*_{{\mathrm{BI}}}}\left( {{\theta _{{\mathrm{BI}}}}} \right){\mathbf{a}}_{{\mathrm{BI}}}^T\left( {{\theta _{{\mathrm{BI}}}}} \right)}}{{\left\| {{{\mathbf{a}}_{{\mathrm{BI}}}}\left( {{\theta _{{\mathrm{BI}}}}} \right)} \right\|^2}}.
\end{align}

Given $\mathbf{R}_\mathrm{s}$ and $\bm{\varphi}$, the optimal SIRS phase shift is given by
\begin{align}
	\label{IRS_BF_S}
		\phi_n^{\star} = -\arg \left[{{{\mathbf{a}}_{{\mathrm{IT}}}}\left( {{\vartheta _{{\mathrm{TI}}}}} \right)} \right]_n  - \arg \left[ {{{\mathbf{a}}_{{\mathrm{IB}}}}\left( {{\vartheta _{{\mathrm{IB}}}}} \right)} \right]_n , \forall n \in \mathcal{N}.
\end{align}

Given $\mathbf{\Phi}^{\star}$ and $\mathbf{R}_\mathrm{s}^{\star}$, the CRB w.r.t. $\bm{\varphi}$ is given by
\begin{align}
	\operatorname{CRB} (\bm{\varphi}) \!=\!  \frac{{3\sigma _{\mathrm{T}}^2 {\lambda ^2} }}{{2T{|\alpha _{{\mathrm{BI}}}|^2}{\left| {{\alpha _{{\mathrm{ITI}}}}} \right|^2}{\pi ^2} {\bar d^2} {P_0}M{N^2}( {{L^3} - L} ){F_{\mathrm{T}}}( \bm{\varphi}  ) }}.
	\label{sensing_crb}
\end{align}


\begin{Proposition}
	\label{pro:2D}
	For any given SIRS's 3D orientation $\bm{\varphi}_\mathrm{3D} = \left[\varphi_x, \varphi_y, \varphi_z\right]^T$ and location, there always exists a 2D orientation solution $\bm{\varphi}_\mathrm{2D}^{\star} = \left[\varphi_x^{\star}, \varphi_y^{\star}, 0\right]^T$ satisfying $\operatorname{CRB} \left(\bm{\varphi}_\mathrm{2D}^{\star}\right) = \operatorname{CRB} \left(\bm{\varphi}_\mathrm{3D}\right)$.
\end{Proposition}
{\it{Proof:}} Please refer to Appendix A. ~$\hfill\blacksquare$

Based on Proposition \ref{pro:2D}, we can reexpress $q_3$, $q_6$, and $q_9$ as $\bar q_3 = \cos {\varphi _x}\sin {\varphi _y}$, $\bar q_6 = - \sin {\varphi _x}$, and $\bar q_9 = \cos {\varphi _x}\cos {\varphi _y}$, respectively. Let $\bar F \left(\varphi _x, \varphi _y\right) = {\cos {\theta _{\mathrm{I}}}}{{\cos }} {\theta _{\mathrm{T}}^{\mathrm{r}}} = (\mathbf{q}_z^T \bar{\mathbf{p}}_{\mathrm{I}})(\mathbf{q}_z^T \bar{\mathbf{p}}_{\mathrm{T}})$ with $\mathbf{q}_{z} = (\bar q_3,\bar q_6,\bar q_9)^T$, $\bar{\mathbf{p}}_{\mathrm{I}} = \frac{{\mathbf{p}}_{\mathrm{I}}}{\left\|{\mathbf{p}}_{\mathrm{I}}\right\|}$, and $\bar{\mathbf{p}}_{\mathrm{T}} = \frac{{\mathbf{p}}_{\mathrm{I}}-{\mathbf{p}}_{\mathrm{T}}}{\left\|{\mathbf{p}}_{\mathrm{I}}-{\mathbf{p}}_{\mathrm{T}}\right\|}$. 
Then, problem \eqref{pro:CRB} is reformulated as
\begin{subequations}
	\label{pro:CRB2}
	\begin{align}
		\mathop {\max }\limits_{\varphi_x, \varphi_y} \; &\bar F \left(\varphi _x, \varphi _y\right) 
		\mathrm{s.t.} \; \;
		& {x_{\mathrm{I}}}{\bar q_3} + {y_{\mathrm{I}}}{\bar q_6} + {z_{\mathrm{I}}}{\bar q_9} \ge 0, \label{BS2D} 
		& ( {{x_{\mathrm{I}}} \!-\! {x_{\mathrm{T}}}} ){\bar q_3} \!+\! ( {{y_{\mathrm{I}}} \!-\! {y_{\mathrm{T}}}} ){\bar q_6} \!+\! ( {{z_{\mathrm{I}}} \!-\! {z_{\mathrm{T}}}} ){\bar q_9} \ge 0. \label{target2D}
	\end{align}
\end{subequations}

Let $\mathbf{\Delta}_1 = (\mathbf{\Delta}_{1,x},\mathbf{\Delta}_{1,y},\mathbf{\Delta}_{1,z})^T = \bar{\mathbf{p}}_{\mathrm{I}}+ \bar{\mathbf{p}}_{\mathrm{T}}$, we provide the optimal solution to problem \eqref{pro:CRB2} in the following proposition.
\begin{Proposition}
	\label{pro:sensing}
	For sensing-only case, the optimal rotation angles are given by
	\begin{align}
		\varphi_x^\star = -\arcsin \frac{\mathbf{\Delta}_{1,y}}{\|\mathbf{\Delta}_{1}\|}, \;\;
		\varphi_y^\star = \arctan \frac{\mathbf{\Delta}_{1,x}}{\mathbf{\Delta}_{1,z}}. \label{phi_sen}
	\end{align}
\end{Proposition}
{\it{Proof:}} Please refer to Appendix B. ~$\hfill\blacksquare$







\subsection{Communication-Only Case}
Next, for the communication-only case, the SNR maximization problem is given by
\begin{subequations}
	\label{pro:communication}
	\begin{align}
		\mathop {\max}\limits_{\mathbf{\Phi}, \mathbf{W}_\mathrm{U},\bm{\varphi}} \;\; & {{{F_\mathrm{U}}\left( {\bm{\varphi }} \right)}{{{ {{\mathbf{h}}_\mathrm{U}^H{\mathbf{\Phi }}{\bar{\mathbf{H}}_{{\mathrm{BI}}}}{{\mathbf{W}}_\mathrm{U}}}\bar{\mathbf{H}}_{{\mathrm{BI}}}^H \mathbf{\Phi }^H {\mathbf{h}}_\mathrm{U}}}}} 
		\mathrm{s.t.} \;\;\;\; 
		& \operatorname{tr}\left(\mathbf{W}_\mathrm{U}\right)  \le P_0,
		&\mathbf{W}_\mathrm{U} \succeq 0, 
		& \operatorname{rank} \left(\mathbf{W}_\mathrm{U}\right) = 1, 
		& ( {{x_{\mathrm{I}}} \!-\! {x_{\mathrm{U}}}} ){q_3} \!+\! ( {{y_{\mathrm{I}}} \!-\! {y_{\mathrm{U}}}} ){q_6} + ( {{z_{\mathrm{I}}} \!-\! {z_{\mathrm{U}}}} ){q_9} \ge 0, 
		&\eqref{BSrotation}, \eqref{rank1}.
	\end{align}
\end{subequations}

Given $\mathbf{\Phi}$ and $\bm{\varphi}$, the optimal beamforming at the BS is given by
\begin{align}
	\label{BS_BF_C}
	{\mathbf{W}}_{\mathrm{U}}^{\star} = {P_0}\frac{{{{\mathbf{a}}^*_{{\mathrm{BI}}}}\left( {{\theta _{{\mathrm{BI}}}}} \right){\mathbf{a}}_{{\mathrm{BI}}}^T\left( {{\theta _{{\mathrm{BI}}}}} \right)}}{{\left\| {{{\mathbf{a}}_{{\mathrm{BI}}}}\left( {{\theta _{{\mathrm{BI}}}}} \right)} \right\|^2}}.
\end{align}
Given ${\mathbf{W}}_{\mathrm{U}}$ and $\bm{\varphi}$, the optimal SIRS phase shift is given by
\begin{align}
	\label{IRS_BF_C}
	\phi_n^{\star} = -\arg \left[{{\mathbf{a}}}_\mathrm{U}\left( \theta _{\mathrm{I,U}} \right) \right]_n  - \arg \left[ {{{\mathbf{a}}_{{\mathrm{IB}}}}\left( {{\vartheta _{{\mathrm{IB}}}}} \right)} \right]_n , \forall n \in \mathcal{N}.
\end{align}

Given $\mathbf{\Phi}^{\star}$ and ${\mathbf{W}}_{\mathrm{U}}^{\star}$, the objective function of problem \eqref{pro:communication} is reduced to $F_\mathrm{U}\left( {\bm{\varphi }} \right)$. Similar to Proposition \ref{pro:2D}, it can be readily verified that the SIRS's 2D orientation is sufficient to achieve the optimal performance of 3D orientation and the optimal rotation angles are given by
\begin{align}
	\varphi_x^\star = -\arcsin \frac{\mathbf{\Delta}_{2,y}}{\|\mathbf{\Delta}_{2}\|}, \;\;
	\varphi_y^\star = \arctan \frac{\mathbf{\Delta}_{2,x}}{\mathbf{\Delta}_{2,z}}, \label{phi_com}
\end{align}
where $\mathbf{\Delta}_2 = (\mathbf{\Delta}_{2,x},\mathbf{\Delta}_{2,y},\mathbf{\Delta}_{2,z})^T = \bar{\mathbf{p}}_{\mathrm{I}}+\bar{\mathbf{p}}_{\mathrm{U}}$ with $\bar{\mathbf{p}}_{\mathrm{U}} = \frac{{\mathbf{p}}_{\mathrm{I}}-{\mathbf{p}}_{\mathrm{U}}}{\left\|{\mathbf{p}}_{\mathrm{I}}-{\mathbf{p}}_{\mathrm{U}}\right\|}$.

\subsection{Co-located User and Target Case}
To draw more useful insight, we consider a special case where the sensed target also acts as a communication user. A typical example is a UAV or connected vehicle that receives downlink data from the BS while being sensed for localization and trajectory tracking \cite{colocated}. When the user and the target are co-located, their departure angles from the SIRS are the same, which yields $\mathbf a_{\mathrm U}(\theta_{\mathrm I,U}) = \mathbf a_{\mathrm{IT}}(\theta_{\mathrm{IT}})$ and $F_{\mathrm U}(\bm\varphi)
= F_{\mathrm T}(\bm\varphi)$. Based on \eqref{BS_BF_S}, \eqref{IRS_BF_S}, \eqref{BS_BF_C}, and \eqref{IRS_BF_C}, the SNR-constrained CRB minimization problem is formulated as
\begin{subequations}
	\label{pro:co}
	\begin{align}
		\mathop {\max }\limits_{\varphi_x, \varphi_y} \;\;\; &{\cos {\theta _{\mathrm{I}}}}{{\cos }} {\theta _{\mathrm{T}}^{\mathrm{r}}} 
		\mathrm{s.t.} \;\;\;\;
		& {\cos {\theta _{\mathrm{I}}}}{{\cos }} {\theta _{\mathrm{T}}^{\mathrm{r}}}{|\alpha _{{\mathrm{U}}}|^2}{|\alpha _{{\mathrm{BI}}}|^2}P_0N^2M/{\sigma _{{\mathrm{U}}}^2} \ge \Gamma, \label{con:commu}
		& \eqref{BS2D}, \eqref{target2D}.
	\end{align}
\end{subequations}

Let $\bar \alpha$ denote the angle between $\mathbf{\bar{p}}_{\mathrm I}$ and $\mathbf{\bar{p}}_{\mathrm T}$, i.e., $\cos \bar{\alpha} = \bar{\mathbf{p}}_{\mathrm{I}}^T \bar{\mathbf{p}}_{\mathrm{T}} \in (-1,1)$. The closed-form expressions of the optimized solution to problem \eqref{pro:co} are derived in the following proposition.
\begin{Proposition}
	\label{proposition:co}
	If the condition $\cos \bar{\alpha} \ge 2\bar{\Gamma} - 1$
	is satisfied with $\bar \Gamma = {\sigma _{{\mathrm{U}}}^2}\Gamma / ({|\alpha _{{\mathrm{U}}}|^2}{|\alpha _{{\mathrm{BI}}}|^2}P_0N^2M)$, the optimal rotation angles are given by
	\begin{align}
		\varphi_x^\star = -\arcsin \frac{\mathbf{\Delta}_{1,y}}{\|\mathbf{\Delta}_1\|}, \;\;
		\varphi_y^\star = \arctan \frac{\mathbf{\Delta}_{1,x}}{\mathbf{\Delta}_{1,z}}.
	\end{align}
	\end{Proposition}
{\it{Proof:}} Please refer to Appendix C. ~$\hfill\blacksquare$

\subsection{Single User Case}
In this case, to independently characterize the impact of the spatial correlation on the ISAC performance, we consider a widely adopted idealized assumption with $F_{\mathrm{T}}(\bm{\varphi}) \approx 1$ and $F_{\mathrm{U}}(\bm{\varphi}) \approx 1$. Then, the optimization problem is formulated as 
\begin{subequations}
	\label{pro:STSU}
	\begin{align}
		\mathop {\max }\limits_{\substack{\mathbf{\Phi}, \mathbf{W}_\mathrm{U},  \mathbf{R}_\mathrm{s}, \bm{\varphi}}}  &{{\left| {{\mathbf{a}}_{{\mathrm{IT}}}^T{\left( \bar \vartheta _{{\mathrm{TI}}} \right)}{\mathbf{\Phi }}{{\mathbf{a}}_{{\mathrm{IB}}}}\left( {{\vartheta _{{\mathrm{IB}}}}} \right)} \right|^2}{\mathbf{a}}_{{\mathrm{BI}}}^T\left( {{\theta _{{\mathrm{BI}}}}} \right){{\mathbf{R}}_{\mathrm{x}}}{{\mathbf{a}}^*_{{\mathrm{BI}}}}\left( {{\theta _{{\mathrm{BI}}}}} \right)}  
		\mathrm{s.t.} \;\; & {{{{{ {{\mathbf{h}}_\mathrm{U}^H{\mathbf{\Phi }}{\bar{\mathbf{H}}_{{\mathrm{BI}}}}{{\mathbf{W}}_\mathrm{U}}}\bar{\mathbf{H}}_{{\mathrm{BI}}}^H \mathbf{\Phi }^H {\mathbf{h}}_\mathrm{U}}}}}}\ge \sigma _\mathrm{U}^2 \Gamma_\mathrm{U}, 
		& \operatorname{tr}\left(\mathbf{W}_\mathrm{U}\right) + \operatorname{tr}\left(\mathbf{R}_\mathrm{s}\right) \le P_0, \label{P0}
		& \mathbf{R}_\mathrm{s} \succeq 0, \label{Rs2}
		&\mathbf{W}_\mathrm{U} \succeq 0, \label{Wu}
		& \operatorname{rank} \left(\mathbf{W}_\mathrm{U}\right) = 1, \label{rankWu}
		& \eqref{BSrotation}, \eqref{targetrotation}, \eqref{userrotation}, \eqref{rank1}.
	\end{align}
\end{subequations}
Given $\mathbf{\Phi}$ and $\bm{\varphi}$, problem \eqref{pro:STSU} is reduced to
\begin{subequations}
	\label{pro:STSU_tr}
	\begin{align}
		\mathop {\max }\limits_{\mathbf{W}_\mathrm{U},\mathbf{R}_\mathrm{s}} \; & {\mathbf{a}}_{{\mathrm{BI}}}^T\left( {{\theta _{{\mathrm{BI}}}}} \right){{\mathbf{R}}_{\mathrm{x}}}{{\mathbf{a}}^*_{{\mathrm{BI}}}}\left( {{\theta _{{\mathrm{BI}}}}} \right)  
		\mathrm{s.t.} \;\;\; & {\left| {{\tilde {\alpha} _{{0}}}} \right|^2}{\left| {{\alpha _{\mathrm{U}}}} \right|^2}{\left| {{\mathbf{a}}_{\mathrm{U}}^T\left( {{\theta _{{\mathrm{I}},{\mathrm{U}}}}} \right){\mathbf{\Phi }}{{\mathbf{a}}_{{\mathrm{IB}}}}\left( {{\vartheta _{{\mathrm{IB}}}}} \right)} \right|^2} \nonumber
		&\times {\mathbf{a}}_{{\mathrm{BI}}}^T\left( {{\theta _{{\mathrm{BI}}}}} \right){{\mathbf{W}}_{\mathrm{U}}}{{\mathbf{a}}^*_{{\mathrm{BI}}}}\left( {{\theta _{{\mathrm{BI}}}}} \right) \ge \sigma _\mathrm{U}^2{\Gamma _{\mathrm{U}}}, 
		& \eqref{P0}, \eqref{Rs2}, \eqref{Wu}, \eqref{rankWu}.
	\end{align}
\end{subequations}
According to \cite{songISAC}, the optimal solution to the relaxed SDR version of problem \eqref{pro:STSU_tr} is given by
\begin{align}
	\mathbf{W}_\mathrm{U}^\star &= \bar{\mathbf{w}}_\mathrm{U} \bar{\mathbf{w}}_\mathrm{U}^H, \forall k \in \mathcal{K}, 
	\mathbf{R}_\mathrm{s}^\star &= \bar{\mathbf{R}}_\mathrm{s} +  \bar{\mathbf{W}}_\mathrm{U} -  \mathbf{W}_\mathrm{U}^\star,
\end{align}
where $\bar{\mathbf{w}}_\mathrm{U} = ({\mathbf{a}}_{{\mathrm{BI}}}^T \bar{\mathbf{W}}_\mathrm{U} {\mathbf{a}}^*_{{\mathrm{BI}}} )^{-1/2} \bar{\mathbf{W}}_\mathrm{U} {\mathbf{a}}^*_{{\mathrm{BI}}}$. 
There exists an optimal solution $\bar{\mathbf{R}}_\mathrm{s}^\star = 0$. Since the rank bound of an optimal solution $\mathbf{R}_\mathrm{x}^\star$ to problem \eqref{pro:STSU_tr} is given by $\operatorname{rank}^2 \left(\mathbf{R}_\mathrm{x}^\star\right) \le 2$ \cite{beam}, we have $\operatorname{rank} \left(\mathbf{R}_\mathrm{x}^\star\right) = 1$. Then, the optimal solutions to problem \eqref{pro:STSU_tr} are given by
\begin{align}
	\mathbf{R}_\mathrm{s}^\star = 0, \;\;
	\mathbf{w}_\mathrm{U}^\star = \sqrt{P_0} \frac{{\mathbf{a}}^*_{{\mathrm{BI}}}\left( {{\theta _{{\mathrm{BI}}}}} \right)}{\|{\mathbf{a}}_{{\mathrm{BI}}}\left( {{\theta _{{\mathrm{BI}}}}} \right)\|}.
\end{align}
Under the considered setup, the communication signal can illuminate the target and provide the sensing measurements. Consequently, the transmit power required for sensing can be carried by the communication beam, and no dedicated sensing signal is needed. Allocating all transmit power to the communication component does not sacrifice the sensing capability captured by the model.
Given $\mathbf{w}_\mathrm{U}^\star$ and $\mathbf{R}_\mathrm{x}^\star$, problem \eqref{pro:STSU} is reduced to
\begin{subequations}
	\label{pro:STSU1}
	\begin{align}
		\mathop {\max }\limits_{\bm{\varphi}, \mathbf{\Phi}} \;\; &  {\left| {{\mathbf{a}}_{{\mathrm{IT}}}^T{\left( \bar \vartheta _{{\mathrm{TI}}} \right)}{\mathbf{\Phi }}{{\mathbf{a}}_{{\mathrm{IB}}}}\left( {{\vartheta _{{\mathrm{IB}}}}} \right)} \right|^2}  
		\mathrm{s.t.} \;\; 
		& {\left| {{\mathbf{a}}_{\mathrm{U}}^T\left( {{\theta _{{\mathrm{I}},{\mathrm{U}}}}} \right){\mathbf{\Phi }}{{\mathbf{a}}_{{\mathrm{IB}}}}\left( {{\vartheta _{{\mathrm{IB}}}}} \right)} \right|^2} \ge {\bar{\Gamma} _{\mathrm{U}}}, \label{con:snr_c} 
		& \eqref{BSrotation}, \eqref{targetrotation}, \eqref{userrotation}, \eqref{rank1},
	\end{align}
\end{subequations}
where ${\bar{\Gamma} _{\mathrm{U}}} = \frac{\sigma _\mathrm{U}^2{\Gamma _{\mathrm{U}}}}{P_0 M {\left| {{\tilde {\alpha} _{{0}}}} \right|^2}{\left| {{\alpha _{\mathrm{U}}}} \right|^2}}$.
With the optimal SIRS beamforming vector, the objective function of problem \eqref{pro:STSU1} is given by \cite{RA_UAV}
\begin{align}
	g_1 \!=\! \left\{\!\!\! {\begin{array}{*{20}{c}}
 N^2, &{{\rho ^2}{N^2} \ge {{\bar \Gamma }_{\mathrm{U}}},}
 \left(\rho \sqrt{\frac{\bar{\Gamma}_{\mathrm{U}}}{\|\mathbf{u}_{\mathrm{U}}\|^2}} \!+\! \sqrt{N^2 \!-\! \frac{\bar{\Gamma}_{\mathrm{U}}}{\|\mathbf{u}_{\mathrm{U}}\|^2}} \sqrt{1 \!-\! \rho^2}\right)^2,&{{\mathrm{otherwise,}}}
	\end{array}} \right.
 \label{lemma}
\end{align}
where $\rho = \frac{|\mathbf{u}_{\mathrm{U}}^H \mathbf{u}_{\mathrm{T}}|}{\|\mathbf{u}_{\mathrm{U}}\| \|\mathbf{u}_{\mathrm{T}}\|} \in [0, 1]$ denotes the correlation coefficient, with $\mathbf{u}_{\mathrm{T}} \triangleq \operatorname{diag}\left(\mathbf{a}_{\mathrm{IT}}^T(\vartheta_{\mathrm{TI}})\right) \mathbf{a}_{\mathrm{IB}}(\vartheta_{\mathrm{IB}})$, and $\mathbf{u}_{\mathrm{U}} \triangleq \operatorname{diag}\left(\mathbf{a}_{\mathrm{U}}^T(\theta_{\mathrm{I,U}})\right) \mathbf{a}_{\mathrm{IB}}(\vartheta_{\mathrm{IB}})$. It indicates that the rotation angle should be designed to maximize $\rho$ for enhancing the sensing and communication performance through channel subspace rotation. 
In the following proposition, we provide the optimal solution to problem \eqref{pro:STSU1}.
\begin{Proposition} 
	\label{proposition:subspace}
	The optimal SIRS phase shift is given by 
	\begin{align}
		\phi _n^* = -{\arg {{\left[ {{{\bf{a}}_{{\mathrm{IT}}}}\left( {{\vartheta _{{\mathrm{TI}}}}} \right)} \right]}_n} \!-\! \arg {{\left[ {{{\bf{a}}_{{\mathrm{IB}}}}\left( {{\vartheta _{{\mathrm{IB}}}}} \right)} \right]}_n}}, \forall n \in \mathcal{N}.
	\end{align}
	The optimal rotation angles are given by
	\begin{align}
		\varphi_x^\star = -\arcsin \frac{\mathbf{\Delta}_{3,y}}{\|\mathbf{\Delta}_3\|}, \;\;
		\varphi_y^\star = \arctan \frac{\mathbf{\Delta}_{3,x}}{\mathbf{\Delta}_{3,z}},
	\end{align}
	where $\mathbf{\Delta}_3 = (\mathbf{\Delta}_{3,x},\mathbf{\Delta}_{3,y},\mathbf{\Delta}_{3,z})^T$ and $\mathbf{q}_z^* = \frac{\mathbf{\Delta}_{3}}{\|\mathbf{\Delta}_3\|}$ within the feasible set $\mathcal{Q} = \{ \mathbf{q}_z | \mathbf{q}_z^T \mathbf{c}_\mathrm{UT} = 0, \|\mathbf{q}_z\| = 1, \mathbf{q}_z^T \bar{\mathbf{p}}_\mathrm{I} \ge 0, \mathbf{q}^T \bar{\mathbf{p}}_\mathrm{T} \ge 0, \mathbf{q}_z^T \bar{\mathbf{p}}_\mathrm{U} \ge 0 \}$ with $\mathbf{c}_\mathrm{UT} = \bar{\mathbf{p}}_{\mathrm{U}} - \bar{\mathbf{p}}_{\mathrm{T}}$. 
\end{Proposition}
{\it{Proof:}} Please refer to Appendix D. ~$\hfill\blacksquare$

In the following, we restore the practical orientation-dependent aperture gains and consider the general rotation design. Given $\mathbf{W}_\mathrm{U}$, $\mathbf{R}_\mathrm{s}$, and $\mathbf{\Phi}$, problem \eqref{pro:original} is reduced to 
\begin{subequations}
	\label{pro:q}
	\begin{align}
		\mathop {\max }\limits_{ \mathbf{q}_z } \; &(\mathbf{q}_z^T \bar{\mathbf{p}}_{\mathrm{I}}) (\mathbf{q}_z^T \bar{\mathbf{p}}_{\mathrm{T}})  {\left| {{\mathbf{a}}_{{\mathrm{IT}}}^T{\left( \bar \vartheta _{{\mathrm{TI}}} \right)}{\mathbf{\Phi }}{{\mathbf{a}}_{{\mathrm{IB}}}}\left( {{\vartheta _{{\mathrm{IB}}}}} \right)} \right|^2}  
		\mathrm{s.t.} \;\; &  \frac{1}{\Gamma_\mathrm{U}}{ (\mathbf{q}_z^T \bar{\mathbf{p}}_{\mathrm{I}}) (\mathbf{q}_z^T \bar{\mathbf{p}}_\mathrm{U})  }|\alpha_\mathrm{U}|^2 |\alpha_{\mathrm{BI}}|^2 |\mathbf{a}_\mathrm{U}^T(\theta_{\mathrm{I},\mathrm{U}}) \mathbf{\Phi} \mathbf{a}_{\mathrm{IB}}(\vartheta_{\mathrm{IB}})|^2 \nonumber 
		&\times \mathbf{a}_{\mathrm{BI}}^T(\theta_{\mathrm{BI}}) \mathbf{W}_\mathrm{U} \mathbf{a}^*_{\mathrm{BI}}(\theta_{\mathrm{BI}}) 
		- \sigma _\mathrm{U}^2 \ge 0, \label{con:snr} 
		& \mathbf{q}_z^T {\mathbf{p}}_{\mathrm{I}} \ge 0, \label{qi}
		& \mathbf{q}_z^T ({\mathbf{p}}_{\mathrm{I}} - {\mathbf{p}}_{\mathrm{T}}) \ge 0, \label{qit}
		& \mathbf{q}_z^T ({\mathbf{p}}_{\mathrm{I}} - {\mathbf{p}}_\mathrm{U}) \ge 0, \label{qik}
		& \|\mathbf{q}_z\| = 1. \label{con:q}
	\end{align}
\end{subequations}
Let $b_\mathrm{T} (\mathbf{q}_z) = {\mathbf{a}}_{{\mathrm{IT}}}^T{ ( \bar \vartheta _{{\mathrm{TI}}} )} {\mathbf{\Phi }}{{\mathbf{a}}_{{\mathrm{IB}}}} ( {{\vartheta _{{\mathrm{IB}}}}}  )$ and $b_\mathrm{U} (\mathbf{q}_z) = \mathbf{a}_\mathrm{U}^T(\theta_{\mathrm{I},\mathrm{U}}) \mathbf{\Phi}  \times \! \mathbf{a}_{\mathrm{IB}}(\vartheta_{\mathrm{IB}})$. Then, we have ${{\dot b}_{\mathrm{T}}}({{\bf{q}}_z}) \!=\! \frac{{\partial |{b_{\mathrm{T}}}({{\bf{q}}_z}){|^2}}}{{\partial {{\bf{q}}_z}}} \!=\! 2 \operatorname{Re}\{ b_{\mathrm{T}}^*({{\bf{q}}_z})  \times (j\frac{{\pi {d_\mathrm{I}}}}{\lambda }\cos {\vartheta _{{\mathrm{IB}}}}({\bf{a}}_{{\mathrm{IT}}}^T({{\bar \vartheta }_{{\mathrm{TI}}}}){\bf{\Phi D}}{{\bf{a}}_{{\mathrm{IB}}}}({\vartheta _{{\mathrm{IB}}}})){{{\bf{\tilde p}}}_{{\mathrm{IB}}}} + j\frac{{\pi {d_\mathrm{I}}}}{\lambda } \cos {\theta _{{\mathrm{IT}}}}  \times ({\bf{a}}_{{\mathrm{IT}}}^T({{\bar \vartheta }_{{\mathrm{TI}}}}){\bf{D\Phi }}{{\bf{a}}_{{\mathrm{IB}}}}({\vartheta _{{\mathrm{IB}}}})){{{\bf{\tilde p}}}_{{\mathrm{IT}}}})\}$ and ${{\dot b}_\mathrm{U}}({{\bf{q}}_z}) = \frac{{\partial |{b_{\mathrm{U}}}({{\bf{q}}_z}){|^2}}}{{\partial {{\bf{q}}_z}}} = 2\operatorname{Re}\{ b_\mathrm{U}^*({{\bf{q}}_z}) ( j\frac{{\pi{d_{\mathrm{I}}}}}{\lambda }\cos {\vartheta _{{\mathrm{IB}}}}({\bf{a}}_\mathrm{U}^T(\theta_{\mathrm{I},\mathrm{U}}) {\bf{\Phi D}} {{\bf{a}}_{{\mathrm{IB}}}}(\vartheta_{\mathrm{IB}})){{{\bf{\tilde p}}}_{{\mathrm{IB}}}} + j\frac{{\pi{d_{\mathrm{I}}}}}{\lambda }  \times \cos {\theta _{{\mathrm{I}},\mathrm{U}}}({\bf{a}}_\mathrm{U}^T(\theta_{\mathrm{I},\mathrm{U}}){\bf{D\Phi }}{{\bf{a}}_{{\mathrm{IB}}}}(\vartheta_{\mathrm{IB}})){{{\bf{\tilde p}}}_\mathrm{U}} ) \}$ with ${{{\bf{\tilde p}}}_{{\mathrm{IB}}}} = \frac{{ - {{\bf{p}}_{\mathrm{I}}}}}{{\sqrt {{{(x_{\mathrm{B}}^{\mathrm{L}})}^2} + {{(y_{\mathrm{B}}^{\mathrm{L}})}^2}} }}$, ${{{\bf{\tilde p}}}_{{\mathrm{IT}}}} =  - \frac{{{{\bf{p}}_{\mathrm{T}}} - {{\bf{p}}_{\mathrm{I}}}}}{{\sqrt {{{(x_{\mathrm{T}}^{\mathrm{L}})}^2} + {{(y_{\mathrm{T}}^{\mathrm{L}})}^2}} }}$, ${{{\bf{\tilde p}}}_\mathrm{U}} =  - \frac{{{{\bf{p}}_\mathrm{U}} - {{\bf{p}}_{\mathrm{I}}}}}{{\sqrt {{{(x_\mathrm{U}^{\mathrm{L}})}^2} + {{(y_\mathrm{U}^{\mathrm{L}})}^2}} }}$, and ${\bf{D}} = \operatorname{diag} ( - (N - 1), - (N - 3), \cdots ,N - 1)$. The objective function of problem \eqref{pro:q} is rewritten as $f_1 (\mathbf{q}_z) =  {\left| b_\mathrm{T} (\mathbf{q}_z) \right|^2}  \times (\mathbf{q}_z^T \bar{\mathbf{p}}_{\mathrm{I}}) (\mathbf{q}_z^T \bar{\mathbf{p}}_{\mathrm{T}}) $. Constraint \eqref{con:snr} is expressed as $f_{2} (\mathbf{q}_z) - \sigma _\mathrm{U}^2 \ge 0$, where $f_{2} (\mathbf{q}_z) =  \frac{B_\mathrm{U}}{\Gamma_\mathrm{U}} {(\mathbf{q}_z^T \bar{\mathbf{p}}_{\mathrm{I}}) (\mathbf{q}_z^T \bar{\mathbf{p}}_\mathrm{U}) } {{ |b_\mathrm{U}\left(\mathbf{q}_z\right)|^2 }}$ with $B_\mathrm{U} = |\alpha_\mathrm{U}|^2 |\alpha_{\mathrm{BI}}|^2 \mathbf{a}_{\mathrm{BI}}^T(\theta_{\mathrm{BI}}) \mathbf{W}_\mathrm{U} \mathbf{a}^*_{\mathrm{BI}}(\theta_{\mathrm{BI}})$. By using the first-order Taylor approximation, for the given local point $\mathbf{q}_z^{(r)}$ in the $r$-th iteration, we have 
\begin{align}
	f_1 (\mathbf{q}_z) 
	&\approx f_1 (\mathbf{q}_z^{(r)}) + \left(  |b_{\mathrm{T}}(\mathbf{q}_z^{(r)})|^2  \bar{\mathbf{p}}_{\mathrm{I}} ((\mathbf{q}_z^{(r)})^T \bar{\mathbf{p}}_{\mathrm{T}}) \right. \nonumber
	&+ |b_{\mathrm{T}}(\mathbf{q}_z^{(r)})|^2 \bar{\mathbf{p}}_{\mathrm{T}} ((\mathbf{q}_z^{(r)})^T \bar{\mathbf{p}}_{\mathrm{I}}) \nonumber
	&\left. + ((\mathbf{q}_z^{(r)})^T \bar{\mathbf{p}}_{\mathrm{I}}) ((\mathbf{q}_z^{(r)})^T \bar{\mathbf{p}}_{\mathrm{T}}) \dot b_\mathrm{T} (\mathbf{q}_z^{(r)}) \right)^T (\mathbf{q}_z - \mathbf{q}_z^{(r)}) \nonumber 
	&\triangleq \hat f_1^{(r)} (\mathbf{q}_z), 
	f_{2} (\mathbf{q}_z)
	&\approx f_{2} (\mathbf{q}_z^{(r)}) + \left(  \frac{B_\mathrm{U}}{\Gamma_\mathrm{U}}  \right. ( |b_\mathrm{U}(\mathbf{q}_z^{(r)})|^2 ( \bar{\mathbf{p}}_{\mathrm{I}} ( (\mathbf{q}_z^{(r)})^T \bar{\mathbf{p}}_\mathrm{U}) \nonumber
	&+ ( (\mathbf{q}_z^{(r)})^T \bar{\mathbf{p}}_{\mathrm{I}}) \bar{\mathbf{p}}_\mathrm{U} ) 
	+ ((\mathbf{q}_z^{(r)})^T \bar{\mathbf{p}}_{\mathrm{I}}) ((\mathbf{q}_z^{(r)})^T \bar{\mathbf{p}}_\mathrm{U}) \nonumber
	&\times \left.  \dot b_\mathrm{U} (\mathbf{q}_z^{(r)}) ) \right)^T (\mathbf{q}_z - \mathbf{q}_z^{(r)}) \nonumber
	&\triangleq \hat f_{2}^{(r)} (\mathbf{q}_z).
\end{align}
By relaxing the unit-modulus constraint in \eqref{con:q}, problem \eqref{pro:q} can be approximated by
\begin{subequations}
	\label{pro:q1}
	\begin{align}
		\mathop {\max }\limits_{ \mathbf{q}_z } \;\; &\hat f_1^{(r)} (\mathbf{q}_z)  
		\mathrm{s.t.} \;\;\;
		&  \hat f_{2}^{(r)} (\mathbf{q}_z) - \sigma _\mathrm{U}^2 \ge 0, 
		& \eqref{qi}, \eqref{qit}, \eqref{qik},
	\end{align}
\end{subequations}
which is a convex optimization problem and thus can be solved by CVX. Let $\hat{\mathbf{q}}_z$ denote the optimal solution to problem \eqref{pro:q1}. If $\hat{\mathbf{q}}_z$ does not satisfy $\| \hat{\mathbf{q}}_z \| = 1$, we reconstruct a high-quality solution to problem \eqref{pro:q}, i.e., $\mathbf{q}_z^\star = \frac{\hat{\mathbf{q}}_z}{\| \hat{\mathbf{q}}_z \|} = ( q_3^*, q_6^*, q_9^*)^T$.











\subsection{Multi-User Case}
For the general case with the multi-path BS-SIRS channel model and multiple users, we divide all the variables into three blocks, i.e., SIRS rotation $\bm{\varphi}$, BS beamformer $\mathbf{W}_{k}$ and $\mathbf{R}_\mathrm{s}$, as well as SIRS phase-shifts, and then each block is optimized iteratively until convergence is achieved.
\subsubsection{Rotation Optimization}
Given $\mathbf{W}_{k}$, $\mathbf{R}_\mathrm{s}$, and $\mathbf{\Phi}$, problem \eqref{pro:original} is reduced to
\begin{align}
		\label{pro:STMU_rotate}
		\mathop {\min }\limits_{\bm{\varphi}} \operatorname{CRB}{\left( \bar \vartheta _{{\mathrm{TI}}} \right)} \;\;\;
		\mathrm{s.t.} \; \eqref{sinr},\eqref{BSrotation},\eqref{targetrotation},\eqref{userrotation}.
\end{align}
The optimal solution to problem \eqref{pro:STMU_rotate} can be obtained through a two-dimensional search over $\varphi_x \in [-90^\circ,90^\circ]$ and $\varphi_y \in [-90^\circ,90^\circ]$. Moreover, the search space can be reduced by considering the reflection constraints. To further reduce the computational complexity, a genetic algorithm can be employed. Specifically, each chromosome is represented by $\bm{\phi}=[\varphi_x,\varphi_y]^T$. The rotation angles that satisfy the reflection constraints and user SINR requirements are retained in the population. In each generation, the solutions with larger sensing information are selected as parents for the next generation using tournament selection. Blend crossover combines the two angular components of the selected parents, while Gaussian mutation perturbs each angle to preserve population diversity.
\subsubsection{BS Beamforming Optimization}
Let $\mathbf{G}_{k} = \mathbf{g}_k \mathbf{g}_k^H$ with $\mathbf{g}_k^H = {\mathbf{h}}_{k}^H{\mathbf{\Phi }}{{\mathbf{H}}_{{\mathrm{BI}}}}$. Given $\mathbf{\Phi}$ and $\bm{\varphi}$, problem \eqref{pro:original} is reduced to
\begin{subequations}
	\label{pro:TxBF}
	\begin{align}
		\mathop {\max }\limits_{ \left\{\mathbf{W}_{k}\right\},\mathbf{R}_\mathrm{s}} \; &{\operatorname{tr} \left( {{\mathbf{\dot{A}}}{{\mathbf{R}}_{\mathrm{x}}}{{{\mathbf{\dot{A}}}}^H}} \right) - \frac{{{{\left| {\operatorname{tr} \left( {{\mathbf{A}}{{\mathbf{R}}_{\mathrm{x}}}{{{\mathbf{\dot{A}}}}^H}} \right)} \right|}^2}}}{{\operatorname{tr} \left( {{\mathbf{A}}{{\mathbf{R}}_{\mathrm{x}}}{{\mathbf{A}}^H}} \right)}}}  
		\mathrm{s.t.} \;\;\; & \sigma _k^2 - \frac{1}{\Gamma_k}{{F_k}\left( {\bm{\varphi }} \right)} \operatorname{tr} \left(\mathbf{G}_{k}\mathbf{W}_{k}\right) \nonumber
		&+ \sum _{i \in \mathcal{K},i \ne k} {{F_k}\left( {\bm{\varphi }} \right)}\operatorname{tr} \left(\mathbf{G}_{k}\mathbf{W}_{i}\right) \le 0, \forall k \in \mathcal{K}, \label{con:BF_snr}
		&\eqref{txpower}, \eqref{Rs}, \eqref{wk}, \eqref{rankwk}.
	\end{align}
\end{subequations}
By introducing an auxiliary variable $g_2$ and using the Schur's complement, problem \eqref{pro:TxBF} is reformulated as
\begin{subequations}
	\label{pro:TxBF1}
	\begin{align}
		\mathop {\max }\limits_{ \left\{\mathbf{W}_{k}\right\},\mathbf{R}_\mathrm{s},g_2}  &g_2  
		\mathrm{s.t.} \;\;\;\;\;
		& \left[\!\! {\begin{array}{*{20}{c}}
 {\operatorname{tr} ( {{\mathbf{\dot A}}{{\mathbf{R}}_{\mathrm{x}}}{{{\mathbf{\dot A}}}^H}} ) - {g_2}}&{\operatorname{tr} ( {{\mathbf{A}}{{\mathbf{R}}_{\mathrm{x}}}{{{\mathbf{\dot A}}}^H}} )}
 {\operatorname{tr} ( {{\mathbf{\dot A}}{{\mathbf{R}}_{\mathrm{x}}}{{\mathbf{A}}^H}} )}&{\operatorname{tr} ( {{\mathbf{A}}{{\mathbf{R}}_{\mathrm{x}}}{{\mathbf{A}}^H}} )}
		\end{array}} \!\! \right] \succeq 0, 
		& \eqref{con:BF_snr},\eqref{txpower}, \eqref{Rs}, \eqref{wk}, \eqref{rankwk}.
	\end{align}
\end{subequations}
By dropping the rank-one constraint, we obtain the relaxed version of problem \eqref{pro:TxBF1} as problem (SDR67), which is a convex semi-definite program (SDP) that can be optimally solved by convex solvers such as CVX. Let $\left\{\bar{\mathbf{W}}_{k}\right\}$ and $\bar{\mathbf{R}}_\mathrm{s}$ denote the optimal solution to (SDR67). According to \cite{songISAC}, the optimal solution to problem \eqref{pro:TxBF} is given by
\begin{align}
	\mathbf{W}_{k}^\star &= \bar{\mathbf{w}}_{k} \bar{\mathbf{w}}_{k}^H, \forall k \in \mathcal{K}, \label{W_k} 
	\mathbf{R}_\mathrm{s}^\star &= \bar{\mathbf{R}}_\mathrm{s} + \sum_{k \in \mathcal{K}} \bar{\mathbf{W}}_{k} - \sum_{k \in \mathcal{K}} \mathbf{W}_{k}^\star, \label{R_s}
\end{align}
where $\bar{\mathbf{w}}_{k} = (\mathbf{g}_k^H \bar{\mathbf{W}}_{k} \mathbf{g}_k )^{-1/2} \bar{\mathbf{W}}_{k} \mathbf{g}_k$.
\subsubsection{IRS Beamforming Optimization}
Let ${\mathbf{h}}_k^H \mathbf{\Phi} {\mathbf{H}}_\mathrm{BI} = \mathbf{v}^T {\mathbf{H}}_k$ with ${\mathbf{H}}_k = \operatorname{diag}({\mathbf{h}}_k^H) {\mathbf{H}}_\mathrm{BI}$ and $\mathbf{V} = \mathbf{v} \mathbf{v}^H$ satisfying $\mathbf{V} \succeq 0$ and $\operatorname{rank} \left(\mathbf{V}\right) = 1$. Given $\mathbf{W}_{k}$, $\mathbf{R}_\mathrm{s}$, and $\bm{\varphi}$, problem \eqref{pro:original} is reduced to
\begin{subequations}
	\label{pro:IRSBF}
	\begin{align}
		\mathop {\max }\limits_{\mathbf{V}} \;\; & {\frac{{{L^2} \!-\! 1}}{3}} \! \operatorname{tr} ( {\mathbf{R}}_1 {\mathbf{V}} ) \!+\! \operatorname{tr} ( {{{\mathbf{D}}_{\mathrm{IT}}}{{\mathbf{R}}_1}{{\mathbf{D}}_{\mathrm{IT}}}{\mathbf{V}}} ) \!-\! \frac{{{\left| \operatorname{tr} ({{\mathbf{D}_\mathrm{IT}}{{\mathbf{R}}_1}{\mathbf{V}}}) \right|^2}}}{{\operatorname{tr}( {{{\mathbf{R}}_1}{\mathbf{V}}} )}} 
		\mathrm{s.t.} \;\;
		&\sum _{i \in \mathcal{K},i \ne k} {{F_k}\left( {\bm{\varphi }} \right)}\operatorname{tr} \left(\mathbf{\hat H}_{k,i} \mathbf{V}\right) \nonumber
		&- \frac{1}{\Gamma_k}{{F_k}\left( {\bm{\varphi }} \right)} \operatorname{tr} \left(\mathbf{\hat H}_{k,k} \mathbf{V}\right) + \sigma _k^2 \le 0, \forall k \in \mathcal{K}, \label{V_snr}
		& \mathbf{V} \succeq 0, \label{V}
		&{\mathbf{V}}_{n,n}=1, \forall n \in \mathcal{N} \label{rankV},
	\end{align}
\end{subequations}
where $\mathbf{\hat H}_{k,i} = (\mathbf H_k\mathbf W_i\mathbf H_k^H)^T$.
By introducing an auxiliary variable $g_3$ and using the Schur's complement, problem \eqref{pro:IRSBF} is reformulated as
\begin{subequations}
	\label{pro:V}
	\begin{align}
		\mathop {\max }\limits_{\mathbf{V}} \;\; &( {\frac{{{L^2} - 1}}{3}} ) \operatorname{tr} ( {\mathbf{R}}_1 {\mathbf{V}} ) + \operatorname{tr} ( {{{\mathbf{D}}_{\mathrm{IT}}}{{\mathbf{R}}_1}{{\mathbf{D}}_{\mathrm{IT}}}{\mathbf{V}}} ) - g_3 
		\mathrm{s.t.} \;\; 
 & \left[ {\begin{array}{*{20}{c}}
 {{g_3}}&{\operatorname{tr} \left( {{{\mathbf{D}}_{{\mathrm{IT}}}}{{\mathbf{R}}_1}{\mathbf{V}}} \right)}
 {\operatorname{tr} \left( {{{\mathbf{V}}^H}{{\mathbf{R}}_1}{{\mathbf{D}}_{{\mathrm{IT}}}}} \right)}&{\operatorname{tr} \left( {{{\mathbf{R}}_1}{\mathbf{V}}} \right)}
		\end{array}} \right] \succeq \mathbf{0},
		&\eqref{V_snr}, \eqref{V}, \eqref{rankV}.
	\end{align}
\end{subequations}
By dropping the rank-one constraint, we obtain the relaxed version of problem \eqref{pro:V} as problem (SDR71), which is a convex SDP that can be optimally solved by convex solvers such as CVX. 
Overall Algorithm and Computational Complexity: In summary, the proposed algorithm updates the SIRS rotation angles $\bm{\varphi}$, the BS beamforming $\{\mathbf{W}_k\}$ and $\mathbf{R}_s$, and the SIRS beamforming $\bm{\Phi}$ alternately in an iterative manner. Specifically, $\bm{\varphi}$ is updated by applying the genetic algorithm to problem \eqref{pro:STMU_rotate}, while $\{\mathbf{W}_k\}$ and $\mathbf{R}_s$ are updated by solving problem (SDR67), followed by reconstruction in \eqref{W_k} and \eqref{R_s}. With the updated rotation angles and BS beamforming, the SIRS beamforming is optimized by solving problem (SDR71). Let $\mathbf{V}^\star$ denote the optimal solution to problem (SDR71). If $\mathbf{V}^\star$ is not a rank-one matrix, we first generate a number of random vectors $\mathbf{r} \sim \mathcal{CN} (0,\mathbf{I}_N)$and, for each random vector, construct a candidate solution $\mathbf {\tilde v} = e^{j \arg \{(\mathbf{V}^\star)^{1/2} \mathbf{r}\}}$, from which the reflection matrix is reconstructed as $\bm{\Phi}=\operatorname{diag}(\mathbf {\tilde v})$. The above procedures are repeated until the convergence is achieved. 
The complexities of problem (SDR67) and problem (SDR71) are $\mathcal O((KM)^{3.5})$ and $\mathcal O(N^{3.5})$, respectively. For rotation optimization, the complexity of the genetic algorithm is $\mathcal O(P_{\mathrm{GA}}G_{\mathrm{GA}} C_{\mathrm{GA}})$, where $P_{\mathrm{GA}}$ denotes the population size, $G_{\mathrm{GA}}$ denotes the number of generations, and $\mathcal C_{\mathrm{GA}}$ denotes the cost of evaluating one candidate. Thus, the main complexity of the proposed algorithm is given by $\mathcal{O} \left( L_{\mathrm{iter}} \left( P_{\mathrm{GA}}G_{\mathrm{GA}} C_{\mathrm{GA}} \!+\! (K M)^{3.5} \!+\! N^{3.5} \right)\right)$, where $L_{\mathrm{iter}}$ denotes the total number of iterations required to achieve convergence.
\section{Numerical Results}
In this section, we provide the simulations to demonstrate the performance of the rotatable SIRS-aided ISAC system. The global coordinates of the BS, SIRS, and target are $[0,0,0]^T$ m, $[20,30,15]^T$ m, and $[0,20,10]^T$ m, respectively. The users are uniformly and randomly distributed within a radius of 5 m centered at $[25,35,0]^T$ m. Without loss of generality, other
system parameters are set as follows: $M=128$, $N=256$, $\lambda = 0.125$ m, $\kappa = 7$ dBsm, $L=4$, $T=100$, $P_0 = 40$ dBm, $d_\mathrm{s} = d_\mathrm{I} = \bar d = \lambda /2$, $\Gamma_{\mathrm{U}} = \Gamma _k = 10$ dB, $\sigma_{\mathrm{U}} = \sigma _k = -80$ dBm, $\forall k \in \mathcal{K}$, $\sigma_\mathrm{T} = -110$ dBm, and $C=5$.
\subsection{Sensing-Only Case}
\begin{figure}[t]
	\centering
	\includegraphics[width=0.85\linewidth]{CRBvsP.eps}
	\vspace{-5pt}
	\caption{CRB versus the transmit power $P_0$.}
	\label{fig:CRB_P}
 \vspace{-5pt}
\end{figure}
We first investigate a special case of the ISAC system with a point target. For comparison, the following rotation design schemes are considered: 1) Sensing-oriented design: the SIRS rotation angles are set based on \eqref{phi_sen}; 2) Communication-oriented design: the SIRS rotation angles are set based on \eqref{phi_com}; 3) Fixed: the SIRS rotation angles are set to $\bm{\varphi} = \mathbf{0}$; 4) ES: the optimized SIRS rotation angles are obtained via the two-dimensional search.
In Fig. \ref{fig:CRB_P}, we plot the CRB versus the transmit power under different number of sensors. First, one can observe that the CRB of all the schemes monotonically decreases with $P_0$, since the received echo strength increases with the total transmit power, thereby improving the sensing performance. Second, it is observed that the CRB decreases by approximately 19 dB as the number of sensors increases from $L=2$ to $L=8$, which is consistent with the result in \eqref{sensing_crb}. This is due to the linear receive beamforming gain and the spatial direction gain of $\mathcal{O}(L^3)$ provided by the sensors. Third, it is observed that the CRB with the rotation angles optimized by the sensing-oriented scheme is close to that obtained by the ES scheme and outperforms those of the other schemes under different transmit power when $L=2$ and $L=8$. Notably, to achieve a CRB of -50 dB, the required transmit power is reduced from 24 dBm to 14 dBm by replacing the fixed rotation scheme with the proposed scheme when $L=8$, which demonstrates the effectiveness of the proposed design. This is due to the larger effective reception and reflection gains provided by rotation optimization, thereby maintaining the sensing performance at a lower transmit power.
\subsection{Single User Case}
Next, we consider the case where the BS serves one target and one user in the case with only a LoS-dominant path. In Fig. \ref{fig:STSU}, we plot the CRB versus the transmit power when $N=32$ and $N=64$. First, one can observe that the CRB of all schemes monotonically decreases with $P_0$, because increasing the transmit power budget improves sensing while satisfying the communication requirement. In particular, the CRB of the proposed scheme decreases by approximately 10 dB when $P_0$ increases from 30 dBm to 40 dBm for both $N=32$ and $N=64$. Second, it is observed that the CRB achieved by the proposed scheme is close to that of the ES scheme in the whole range of transmit power, which demonstrates the effectiveness of the proposed rotation design. In particular, both schemes outperform the fixed scheme even when the number of reflecting elements is halved ($N=32$ versus $N=64$). This is due to the effective aperture gains provided by rotation optimization. Furthermore, the CRB of the proposed scheme decreases by approximately 6 dB when the number of reflecting elements increases from $N=32$ to $N=64$. The results demonstrate that rotation optimization can provide additional DoFs and achieve better sensing performance with fewer reflecting elements, highlighting the importance of jointly designing the SIRS orientation and beamforming for ISAC.  
