\begin{align}
	&\frac{{( {{x_{\mathrm{I}}} \!\!-\!\! {x_{\mathrm{T}}}} ) \! \cos {\varphi _x^{\star}} \! \sin {\varphi _y^{\star}} \!-\! ( {{y_{\mathrm{I}}} \!\!-\!\! {y_{\mathrm{T}}}} ) \! \sin {\varphi _x^{\star}} \!+\! ( {{z_{\mathrm{I}}} \!\!-\!\! {z_{\mathrm{T}}}} ) \! \cos {\varphi _x^{\star}} \! \cos {\varphi _y^{\star}}}}{{\sqrt {{{( {{x_{\mathrm{I}}} - {x_{\mathrm{T}}}} )}^2} + {{( {{y_{\mathrm{I}}} - {y_{\mathrm{T}}}} )}^2} + {{( {{z_{\mathrm{I}}} - {z_{\mathrm{T}}}} )}^2}} }} \nonumber
	&= \frac{{( {{x_{\mathrm{I}}} - {x_{\mathrm{T}}}} ){q_3} + ( {{y_{\mathrm{I}}} - {y_{\mathrm{T}}}} ){q_6} + ( {{z_{\mathrm{I}}} - {z_{\mathrm{T}}}} ){q_9}}}{{\sqrt {{{( {{x_{\mathrm{I}}} - {x_{\mathrm{T}}}} )}^2} + {{( {{y_{\mathrm{I}}} - {y_{\mathrm{T}}}} )}^2} + {{( {{z_{\mathrm{I}}} - {z_{\mathrm{T}}}} )}^2}} }}, \label{con:cosi}
	&\frac{{{x_{\mathrm{I}}}\cos {\varphi _x^{\star}}\sin {\varphi _y^{\star}} - {y_{\mathrm{I}}}\sin {\varphi _x^{\star}} + {z_{\mathrm{I}}}\cos {\varphi _x^{\star}}\cos {\varphi _y^{\star}}}}{{\sqrt {x_{\mathrm{I}}^2 + y_{\mathrm{I}}^2 + z_{\mathrm{I}}^2} }} \nonumber
	&= \frac{{{x_{\mathrm{I}}}{q_3} + {y_{\mathrm{I}}}{q_6} + {z_{\mathrm{I}}}{q_9}}}{{\sqrt {x_{\mathrm{I}}^2 + y_{\mathrm{I}}^2 + z_{\mathrm{I}}^2} }} \label{con:cost}.
\end{align}
The conditions under which \eqref{con:cosi} and \eqref{con:cost} hold are given by
\begin{align}
	&\cos {\varphi _x^{\star}}\sin {\varphi _y^{\star}} = q_3, \label{con1}
	&-\sin {\varphi _x^{\star}} = q_6, \label{con2}
	&\cos {\varphi _x^{\star}}\cos {\varphi _y^{\star}} = q_9. 
\end{align}
Next, we prove
\begin{align}
	& q_3^2+q_9^2 \le 1, \label{proof1}
	& |q_6| \le 1, \label{proof2}
	& q_3^2+q_6^2+q_9^2 = 1. \label{proof3}
\end{align}
Note that $\sin^2\varphi_x+\cos^2\varphi_x = 1$, it follows that
\begin{align}
	&1 \!-\! (q_3^2 \!+\! q_9^2) \! = \! \sin^2\varphi_x \!+\! \cos^2\varphi_x \!-\! \cos^2\varphi_x\sin^2\varphi_y\cos^2\varphi_z \nonumber
	&-\sin^2\varphi_x\sin^2\varphi_z-2\cos\varphi_x\sin\varphi_y\cos\varphi_z \nonumber
	&\times \sin\varphi_x\sin\varphi_z-\cos^2\varphi_x\cos^2\varphi_y \nonumber 
	&=\sin^2\varphi_x\cos^2\varphi_z+\cos^2\varphi_x\sin^2\varphi_y\sin^2\varphi_z \nonumber
	&- 2\cos\varphi_x\sin\varphi_y\sin\varphi_z\sin\varphi_x\cos\varphi_z \nonumber
	&=(\cos\varphi_x\sin\varphi_y\sin\varphi_z-\sin\varphi_x\cos\varphi_z)^2 \ge 0.
\end{align}
The left hand side (LHS) of \eqref{proof2} can be rewritten as $q_6 = \left(\cos {\varphi _x}\sin {\varphi _y},-\sin {\varphi _x}\right) \left(\sin {\varphi _z},\cos {\varphi _z}\right)$.
Based on Cauchy–Schwarz inequality, we have 
\begin{align}
	|q_6| &\le \sqrt{\cos {\varphi _x}^2\sin {\varphi _y}^2+\sin {\varphi _x}^2}\sqrt{\sin {\varphi _z}^2+\cos {\varphi _z}^2} \nonumber
	&\le \sqrt{\cos {\varphi _x}^2\sin {\varphi _y}^2+\sin {\varphi _x}^2} \nonumber
	& \le \sqrt{\cos {\varphi _x}^2+\sin {\varphi _x}^2} = 1.
\end{align}

By substituting \eqref{gCCS} into the LHS of \eqref{proof3}, we have
\begin{align}
	q_3^2 + q_6^2 + q_9^2 = & \cos^2\varphi_x \sin^2\varphi_y (\cos^2\varphi_z + \sin^2\varphi_z) \nonumber
	&aa+ \sin^2\varphi_x (\sin^2\varphi_z + \cos^2\varphi_z) \nonumber
	= & \cos^2\varphi_x \sin^2\varphi_y + \sin^2\varphi_x + \cos^2\varphi_x \cos^2\varphi_y \nonumber
	= & \cos^2\varphi_x (\sin^2\varphi_y + \cos^2\varphi_y) + \sin^2\varphi_x \nonumber
	= & \cos^2\varphi_x + \sin^2\varphi_x = 1.
\end{align}
Based on \eqref{con1} and \eqref{con2}, we derive $\bm{\varphi}_\mathrm{2D}^{\star} = \left[\varphi_x^{\star}, \varphi_y^{\star}, 0\right]^T$ with
\begin{align}
	\varphi_x^{\star} = - \arcsin q_6, \;\; \varphi_y^{\star} = \arcsin \frac{q_3}{\sqrt {q_3^2 + q_9^2}}.
\end{align}
The proof is thus completed.

















