The proof is given in Appendix~ef{app:rate}. Along the own-power direction of a link with SINR $\gamma$, the contraction factor $1-f''/\phi''$ is $\approx1-2/\gamma$ for FP/WMMSE, $\approx1-2/\log\gamma$ for SEFP/XMMSE and $1/(1+\gamma)^2$ for ICT. The first explains why closed-form FP needs thousands of iterations at 20--30\,dB, the second why SEFP/XMMSE need tens, and the third why the residual slowness of ICT, where present, comes from the shared interference directions rather than from the own-signal term.
\subsection{The Transformed Problem and Its Convergence}
Substituting \eqref{eq:ict} into \eqref{eq:wsr} gives the equivalent problem
 egin{equation}
\max_{\mathbf x\in\mathcal X,\, oldsymbol\kappa\ge0}\ \sum_iw_i ig[\Om(\kappa_ia_i(\mathbf x))-\kappa_ib_i(\mathbf x) ig],
\label{eq:transformed}
\end{equation}
whose maximization over $ oldsymbol\kappa$ recovers \eqref{eq:wsr} exactly. Alternating between the closed-form update $\kappa_i=a_i/(b_i(a_i+b_i))$ and the maximization over $\mathbf x$ is an MM algorithm with the ICT surrogate. The degenerate anchor $a_i=0$ (zero price, flat surrogate) is excluded by $p_{\min}>0$, exactly as for FP and WMMSE.
 egin{proposition}[Convergence]
\label{prop:conv}
Let $\mathcal X$ be compact and let the $\mathbf x$ step maximize the ICT surrogate exactly (or, for the scheduling problem, maximize the separable surrogate over the schedule and the powers). Then the WSR is non-decreasing along the iterates and converges, and every limit point $\mathbf x^\star$ with $a_i(\mathbf x^\star)>0$ for all $i$ is a stationary point of \eqref{eq:wsr} (a KKT point when $\mathcal X$ is described by the box or power constraints of Section~ef{sec:prelim}).
\end{proposition}
 egin{IEEEproof}
By Theorem~ef{thm:ict}, the surrogate $S(\mathbf x; ar{\mathbf x})=\sum_iw_i[\Om(\kappa_i^\star( ar{\mathbf x})a_i(\mathbf x))-\kappa_i^\star( ar{\mathbf x})b_i(\mathbf x)]$ satisfies $S\le f$ with equality at $ ar{\mathbf x}$, so that $f(\mathbf x^{t+1})\ge S(\mathbf x^{t+1};\mathbf x^t)\ge S(\mathbf x^t;\mathbf x^t)=f(\mathbf x^t)$; since $f$ is bounded on $\mathcal X$, $f(\mathbf x^t)$ converges. $S$ is continuously differentiable in $(\mathbf x, ar{\mathbf x})$ wherever $a_i>0$, with $
abla_{\mathbf x}S( ar{\mathbf x}; ar{\mathbf x})=
abla f( ar{\mathbf x})$ by Proposition~ef{prop:omega}(d). These are the hypotheses of the MM convergence theorem of \cite[Thm.~1]{Sun17} and \cite[Thm.~2]{Razaviyayn13}, which gives the stationarity of the limit points; for the scheduling problem, the argument of \cite[Prop.~1]{ShenYuII} applies verbatim with the ICT surrogate, since the schedule is updated by an exact maximization of the separable surrogate.
\end{IEEEproof}
\section{Power Control and Scheduling in SISO Networks}
\label{sec:siso}
\subsection{Power Control: Proposed Approach}
For fixed $ oldsymbol\kappa$, the surrogate of \eqref{eq:transformed} in the SISO power-control model is $\sum_iw_i\Om(\kappa_ig_{ii}p_i)-\sum_i\mu_ip_i+\mathrm{const}$, with $\mu_i=\sum_{j
e i}w_j\kappa_jg_{ji}$ the total price that link $i$ pays for the interference it causes; it is concave and separable. Setting the derivative to zero, $w_i\kappa_ig_{ii}/hof(\kappa_ig_{ii}p_i)=\mu_i$, and using $hof^2/(1+hof)=u$, we obtain
 egin{equation}
ho_i= rac{w_i\kappa_ig_{ii}}{\mu_i},\qquad p_i=\Big[ rac{ho_i^2}{(1+ho_i)\kappa_ig_{ii}}\Big]_{p_{\min}}^{P_{\max}}.
\label{eq:pc}
\end{equation}
The resulting procedure is summarized in Algorithm~ef{alg:pc}. Each iteration costs $O(K^2)$, exactly as closed-form FP \cite{ShenYuI} and SEFP \cite{Jiao26}, whose updates have the same structure with $ho_i^2/(1+ho_i)$ replaced by the corresponding QT expressions. The quantity $ho_i$ has a direct interpretation: it is the SINR that link $i$ would attain if it responded optimally to the current prices, and $w_i\log(1+ho_i)$ is the unclipped value of its subproblem. In power control, the ICT and FP updates differ in the value they produce rather than in its sign; the sign of the own-signal term matters in scheduling, where it decides whether a cell transmits at all (Section~ef{sec:sched}).
 egin{algorithm}[t]
\caption{ICT power control (ICT-PC)}
\label{alg:pc}
 egin{algorithmic}[1]
\STATE Initialize $p_i\in[p_{\min},P_{\max}]$.
\REPEAT
\STATE $a_i\leftarrow g_{ii}p_i$, $b_i\leftarrow\sum_{j
e i}g_{ij}p_j+\sigma^2$, $\kappa_i\leftarrow a_i/(b_i(a_i+b_i))$.
\STATE $\mu_i\leftarrow\sum_{j
e i}w_j\kappa_jg_{ji}$, $ho_i\leftarrow w_i\kappa_ig_{ii}/\mu_i$.
\STATE $p_i\leftarrow[ho_i^2/((1+ho_i)\kappa_ig_{ii})]_{p_{\min}}^{P_{\max}}$ for all $i$.
\UNTIL{the WSR has converged}
\end{algorithmic}
\end{algorithm}
