\SetArgSty{textnormal}
\SetKwInput{KwInit}{Initialize}
\caption{BCD Algorithm for Solving Problem \eqref{p1}}
\label{alg:robust_bcd}
\KwInit{$\bm t^{(r)}$, $\{\boldsymbol w_k^{(r)}\}$, $\boldsymbol R_{\rm A}^{(r)}$, and set $r=0$.}
\SetEndCharOfAlgoLine{.}
\Repeat{exit conditions are met}{
 \SetEndCharOfAlgoLine{;}
 Update $\gamma_{\rm B}^{(r+1)}$ by bisection search\;
 Update $\overline{\boldsymbol W}_k^{(r+1)}$ and $\overline{\boldsymbol R}^{(r+1)}$ via \eqref{p2} at $\gamma_{\rm B}^{(r+1)}$\; 
 Construct $\boldsymbol w_k^{(r+1)}$ and $\boldsymbol R_{\rm A}^{(r+1)}$ via \eqref{SDR_optimal}\;
 Update $\alpha_k^{(r+1)}$ via \eqref{eq:alpha_update_position}\;
 Update $\bm t^{(r+1)}$ and $\gamma^{(r+1)}$ via \eqref{p3_sca}\;
 Update $r=r+1$\;
}
\KwRet{$\bm t^\star$, $\boldsymbol w_k^\star$, and $\boldsymbol R_{\rm A}^\star$}\;
\end{algorithm}
