As shown in Fig.~2, we adopt a two-phase protocol~\cite{xu2025joint} with PA positioning, information transmission, and total frame durations $T_{\rm pos}$, $T_{\rm tx}$, and $T_{\rm tot} \ge T_{\rm pos} + T_{\rm tx}$, respectively. The position-dependent power attenuation of the $n$-th PA is $p_{n} = e^{-2\alpha\|\bm{\psi}_n^{\mathrm{FP}}-\bm{\psi}_{n}^{\mathrm{Pin}}\|_2}$~\cite{hu2025}, where $\alpha = \lambda_g \epsilon_r \pi f_c^2c^{-2} \text{tan}(\delta_e)\in \mathbb{R}^+$ is the attenuation constant, with dielectric constant $\epsilon_r$ and effective dielectric loss tangent $\text{tan}(\delta_e)$. With previous PA position $\tilde{\bm{\psi}}_{n}^{\mathrm{Pin}}=[\tilde{x}_{n}^{\mathrm{Pin}},0,z_n]^\top$ and displacement $\Delta_{n}= |x_n^{\rm Pin} - \tilde{x}_n^{\rm Pin}|$, the circuit and PA movement energies are $E_{\rm Cir} = N(T_{\rm tx} + T_{\rm pos})P_{\rm cir}$ and $E_{\rm Mov} = \frac{P_{\mathrm{mot}}\sum_{n=1}^{N}\Delta_{n}}{v_{\mathrm{PA}}}$~\cite{xu2025joint}, respectively, where $P_{\rm cir}$, $P_{\rm mot} > 0$, and $v_{\rm PA} > 0$ denote the static circuit power, per-PA motor power, and constant moving speed, respectively. The $n$-th fronthaul link has length and power-delivery factor $\ell_n^{\rm{fib}}=\left\|\bm{\psi}_n^{\mathrm{FP}}-\bm{\psi}^{\rm{BS}}\right\|_2$ and $\eta_n^{\rm{fib}}=e^{-2\alpha_{\mathrm{f}}\ell_n^{\rm{fib}}}$, respectively, where $\alpha_{\rm{f}} =\frac{\ln 10}{20}\kappa_{\rm{f}}$ with fiber attenuation coefficient $\kappa_{\rm{f}}$. Hence, the total consumed energy is
\begin{align}
E_{\mathrm{total}} = \underbrace{\frac{T_{\mathrm{tx}}}{\eta_{\mathrm{BS}}} \sum_{n\in\mathcal{N}} \frac{1}{\eta^{\rm{fib}}_n} \sum_{k\in\mathcal{K}} |w_{k,n}|^2 }_{\text{Transmission},\ E_{\mathrm{Tx}}} +E_{\mathrm{Cir}}+E_{\mathrm{Mov}},
\end{align}
where $\eta_{\mathrm{BS}}\in(0,1]$ is the power-amplifier efficiency at the BS. Importantly, the LoS-favorable PA positions are generally not aligned with the energy-minimizing ones, and this tradeoff jointly shapes the subsequent resource allocation.
\subsection{Channel and Signal Model}
We assume that the BS knows the user locations and the statistical LoS availability of all PA--user links~\cite{ding2025los}. For the $n$-th PA--$u_k$ link, the downlink spherical-wave near-field channel and in-waveguide phase-shift coefficient are~\cite{blockage2025}
\begin{align}\label{eq:channel_user}
h_{n,k}^{\rm L} = \tfrac{ \eta^{1/2} e^{-j\frac{2\pi}{\lambda}\|\bm{\phi}_k-\bm{\psi}_{n}^{\rm Pin}\|}}
 {\|\bm{\phi}_k-\bm{\psi}_{n}^{\rm Pin}\|}, \quad
g_{n} \hspace{-1mm}=\hspace{-0.8mm} e^{-j\frac{2\pi}{\lambda_g}\hspace{-0.5mm}\left\|\hspace{-0.4mm}\bm{\psi}_n^{\rm FP} \hspace{-0.8mm}-\hspace{-0.2mm} \bm{\psi}_{n}^{\rm Pin} \hspace{-0.6mm}\right\|}, \hspace{0.2mm}
\end{align}
respectively, where $\eta=\tfrac{c^2}{16\pi^2f_c^2}$ is the free-space reference channel gain, $\lambda_g=\lambda/\eta_{\mathrm{eff}}$, and $c$, $f_c$, $\lambda$, and $\eta_{\mathrm{eff}}>1$ denote the speed of light, carrier frequency, wavelength, and effective refractive index, respectively~\cite{hu2025}. The blockage-aware channel $h_{n,k}(\chi_{n,k})=\chi_{n,k}h_{n,k}^{\mathrm{L}} \in \mathbb{C}$ models an LoS-dominant regime in which blocked links have negligible non-LoS components~\cite{zhao2026resource}. Accordingly, the equivalent downlink channel of $u_k$ is $\bm{\beta}_k (\bm{\chi}_{k}) = [\beta_{k,1}(\chi_{1,k}),\ldots,\beta_{k,N}(\chi_{N,k})]^\top  \in \mathbb{C}^{N \times 1}$ with $\beta_{k,n}(\chi_{n,k}) = (e^{-\alpha\|\bm{\psi}_n^{\mathrm{FP}}-\bm{\psi}_{n}^{\mathrm{Pin}}\|_2} g_{n}h_{n,k}(\chi_{n,k}) )^*$, $\forall n,k$, and the received signal at $u_k$ is
\begin{align}\label{eq:rx_sig}
\varrho_k = \bm{\beta}_{k}^{H} (\bm{\chi}_{k}) \mathbf{s} + \epsilon_k = \sum_{j\in\mathcal{K}}\bm{\beta}_{k}^{H} (\bm{\chi}_{k})\mathbf{w}_j s_j + \epsilon_k, \forall k,
\end{align}
where $\epsilon_k\sim\mathcal{CN}(0,\sigma_k^2)$ is the additive white Gaussian noise with power $\sigma_k^2$.
\subsection{Problem Formulation}
For a given LoS realization $\bm{\chi}$, the achievable rate of $u_k$ in bit/s/Hz is $R_k(\bm{\chi}_{k}) = \log_2 (1 + \gamma_k(\bm{\chi}_{k}))$ with the SINR
\begin{align}
\gamma_k(\bm{\chi}_{k}) = \tfrac{|\bm{\beta}_k^H (\bm{\chi}_{k}) \mathbf{w}_k|^2}{\sum_{j \neq k} |\bm{\beta}_k^H (\bm{\chi}_{k}) \mathbf{w}_j |^2+ \sigma_k^2}, \forall k.
\end{align}
Let $r_k$ denote the frame-effective transmission rate of $u_k$, corresponding to a coding rate $\tfrac{T_{\rm tot}}{T_{\rm tx}}r_k$ during $T_{\rm tx}$, such that its transmission is successful only if $\tfrac{T_{\rm tx}}{T_{\rm tot}}R_k(\bm{\chi}_k)\ge r_k$. We thus adopt the expected successfully delivered frame-effective sum rate as the performance metric, averaged over $\bm{\chi}$ conditioned on $\mathbf{x}^{\rm Pin} \hspace{-1mm}=\hspace{-1mm}[x_1^{\rm Pin}\hspace{-1mm},\ldots,x_N^{\rm Pin}]^{\hspace{-0.8mm}\top}\hspace{-1mm}$, capturing PA repositioning time, selected transmission rates, and LoS randomness, i.e.,
\begin{align}
\bar{R}  = \mathbb{E}_{\bm{\chi} | \mathbf{x}^{\rm Pin}}  \Big[ \sum\nolimits_{k \in \mathcal{K}}  r_k \mathbb{I}\left\{\tfrac{T_{\rm tx}}{T_{\rm tot}} R_k(\bm{\chi}_{k}) \ge r_k \right\} \Big].
\end{align}
Accordingly, the joint beamforming, PA-positioning, time-allocation, and transmission-rate design is formulated as
\begin{align}
&\underset{\textbf{w}_k, \ r_k, \ x^{\rm{Pin}}_{n},\ T_{\rm pos}, \ T_{\rm tx}} {\rm{maximize}} \hspace{2mm} \bar{R}  \nonumber 
\rm{s.t.}\ &({\rm C1})\hspace{-1mm}:\hspace{-0.7mm} x_{\rm B} \hspace{-1mm}\leq \hspace{-0.8mm} x_{n}^{\rm{Pin}} \hspace{-0.9mm} \leq \hspace{-1mm} x_{\rm B} \hspace{-1mm}+ \hspace{-1mm}L, \hspace{-0.8mm}\forall \hspace{-0.3mm} n\hspace{-0.3mm}, 
({\rm C2})\hspace{-1.2mm}: \hspace{-1.1mm}| \hspace{-0.3mm} x_{n}^{\rm{Pin}} \hspace{-1.2mm}-\hspace{-0.8mm} \Tilde{x}_{n}^{\rm{Pin}} \hspace{-0.4mm}| \hspace{-1mm}\le\hspace{-1.1mm} v_{\rm PA} \hspace{-0.5mm} T_{\hspace{-0.7mm} {\rm pos}}\hspace{-0.4mm}, \hspace{-0.7mm}\forall \hspace{-0.3mm}n\hspace{-0.2mm}, \nonumber 
&({\rm C3})\hspace{-1mm}:\hspace{-0.7mm} \sum_{n \in \mathcal{N}} \frac{1}{\eta^{\rm fib}_n} \sum_{k \in \mathcal{K}} |w_{k,n}|^2 \leq\hspace{-0.5mm} P^{\max}_{\rm Tx}\hspace{-0.5mm}, \nonumber 
&({\rm C4})\hspace{-1mm}:\hspace{-0.7mm} \ E_{\rm total} \leq\hspace{-0.5mm} E^{\max}_{\rm total}, \ ({\rm C5})\hspace{-1mm}:\hspace{-0.7mm} T_{\rm pos} + T_{\rm tx} \le T_{\rm tot}, \nonumber 
&({\rm C6})\hspace{-1mm}:\hspace{-0.5mm} 
\underset{\bm{\chi}_k| \textbf{x}^{\rm Pin}, \bm{\phi}_k}{\text{Pr}} 
\left\{\frac{T_{\rm tx}}{T_{\rm tot}} R_k(\bm{\chi}_{k}) \ge r_k \right\} 
\ge 1 - \delta_k, \, \forall k, \nonumber 
&({\rm C7})\hspace{-1mm}:\hspace{-0.5mm} 
r_k \ge R_{\min,k}^{\mathrm{Req}}, \, \forall k.
\label{eq: formulation}
\end{align}
Constraints (C1) and (C2) confine each PA to its waveguide and limit its displacement to the distance reachable within $T_{\rm pos}$. Constraint (C3) limits the fronthaul-aware BS transmit power to $P_{\rm Tx}^{\rm max}$. Constraints (C4) and (C5) impose the total frame-energy budget $E_{\rm total}^{\rm max}$ and the time allocation. Constraint (C6) guarantees that the selected frame-effective rate $r_k$ is supported by the instantaneous blockage-aware channel with probability at least $1-\delta_k$; while constraint (C7) enforces the per-user minimum rate $R_{\min,k}^{\mathrm{Req}}$.
