\section{\texorpdfstring{Proof of Feasibility of \eqref{SDR_optimal} in Problem \eqref{p2}}{Proof of Feasibility of the Rank-One Recovery}}\label{AppSDR}
Let $\{\overline{\boldsymbol W}_k\}$ and $\overline{\boldsymbol{R}}$ denote a feasible solution of the relaxed SDP for a given $\tau>0$, and define $\overline{\boldsymbol{R}}_{\rm A}\triangleq \overline{\boldsymbol{R}}-\sum_{k\in\mathcal K}\overline{\boldsymbol W}_k$. The constructed rank-one solution is given by $\boldsymbol w_k^\star = (\boldsymbol h_k^H\overline{\boldsymbol W}_k\boldsymbol h_k)^{-1/2}\overline{\boldsymbol W}_k\boldsymbol h_k$ and $\boldsymbol{R}^\star=\overline{\boldsymbol{R}}$.
First, the construction in \eqref{SDR_optimal} yields a rank-one matrix $\boldsymbol W_k^\star=\boldsymbol w_k^\star\boldsymbol w_k^{\star H}$ satisfying
\begin{equation}
\boldsymbol h_k^H\boldsymbol W_k^\star\boldsymbol h_k = \boldsymbol h_k^H\boldsymbol w_k^\star\boldsymbol w_k^{\star H}\boldsymbol h_k = \boldsymbol h_k^H\overline{\boldsymbol W}_k\boldsymbol h_k.
\end{equation}
Thus, the desired signal power in the SINR remains unchanged. Next, we show that $\overline{\boldsymbol W}_k - \boldsymbol W_k^\star \succeq \boldsymbol 0$. For any $\boldsymbol v \in \mathbb C^{M\times 1}$, we have
\begin{equation}
\boldsymbol v^H\!(\overline{\boldsymbol W}\!_{k} \!-\! \boldsymbol W_k^\star)\boldsymbol v \!=\! \boldsymbol v^H\overline{\boldsymbol W}_k\boldsymbol v \!-\! (\boldsymbol h_k^H\overline{\boldsymbol W}_k\boldsymbol h_k)^{-1} |\boldsymbol v^H\overline{\boldsymbol W}_k\boldsymbol h_k|^2.
\end{equation} By the Cauchy--Schwarz inequality, we have
\begin{equation}
(\boldsymbol h_k^H\overline{\boldsymbol W}_k\boldsymbol h_k)(\boldsymbol v^H\overline{\boldsymbol W}_k\boldsymbol v) \ge |\boldsymbol v^H\overline{\boldsymbol W}_k\boldsymbol h_k|^2.
\end{equation}
Therefore, $\boldsymbol v^H(\overline{\boldsymbol W}_k - \boldsymbol W_k^\star)\boldsymbol v \ge 0$ holds for any $\boldsymbol v \in \mathbb C^{M\times 1}$, i.e., $\overline{\boldsymbol W}_k - \boldsymbol W_k^\star \succeq \boldsymbol 0$. We conclude that $\boldsymbol{R}_{\rm A}^\star = \overline{\boldsymbol{R}} - \sum_{k\in\mathcal K}\boldsymbol W_k^\star \succeq \overline{\boldsymbol{R}} - \sum_{k\in\mathcal K}\overline{\boldsymbol W}_k = \overline{\boldsymbol{R}}_{\rm A} \succeq \boldsymbol 0$.
To verify constraint \eqref{Const_p2_sinr}, recall that $\boldsymbol h_k^H\boldsymbol W_k^\star\boldsymbol h_k = \boldsymbol h_k^H\overline{\boldsymbol W}_k\boldsymbol h_k$ and $\boldsymbol{R}^\star = \overline{\boldsymbol{R}}$, which imply $\boldsymbol h_k^H(\boldsymbol{R}^\star - \boldsymbol W_k^\star)\boldsymbol h_k = \boldsymbol h_k^H(\overline{\boldsymbol{R}} - \overline{\boldsymbol W}_k)\boldsymbol h_k$. Thus, we have
\begin{equation}
\frac{\boldsymbol h_k^H\boldsymbol W_k^\star\boldsymbol h_k}{\boldsymbol h_k^H(\boldsymbol{R}^\star - \boldsymbol W_k^\star)\boldsymbol h_k + \sigma_k^2} = \frac{\boldsymbol h_k^H\overline{\boldsymbol W}_k\boldsymbol h_k}{\boldsymbol h_k^H(\overline{\boldsymbol{R}} - \overline{\boldsymbol W}_k)\boldsymbol h_k + \sigma_k^2},
\end{equation}
which confirms that \eqref{Const_p2_sinr} is satisfied.
To verify constraint (\ref{Const_2}), rewrite it as $(1+\eta)\boldsymbol h_q^H\sum_{k\in\mathcal K_c}\boldsymbol W_k\boldsymbol h_q \le \eta(\boldsymbol h_q^H\boldsymbol{R}\boldsymbol h_q + \sigma_q^2)$. Recall that $\overline{\boldsymbol W}_k - \boldsymbol W_k^\star \succeq \boldsymbol 0$ implies $\boldsymbol h_q^H\boldsymbol W_k^\star\boldsymbol h_q \le \boldsymbol h_q^H\overline{\boldsymbol W}_k\boldsymbol h_q$, and $\boldsymbol{R}^\star = \overline{\boldsymbol{R}}$.
Thus, we have
\begin{equation}
\begin{aligned}
  (1+\eta)\boldsymbol h_q^H\sum_{k\in\mathcal K_c}\boldsymbol W_k^\star\boldsymbol h_q &\le (1+\eta)\boldsymbol h_q^H\sum_{k\in\mathcal K_c}\overline{\boldsymbol W}_k\boldsymbol h_q 
  &\le \eta(\boldsymbol h_q^H\overline{\boldsymbol{R}}\boldsymbol h_q + \sigma_q^2)  & = \eta(\boldsymbol h_q^H\boldsymbol{R}^\star\boldsymbol h_q + \sigma_q^2),
\end{aligned}
\end{equation}
which confirms that (\ref{Const_2}) is satisfied. Consequently, all the constraints in the original problem are met.

\section{\texorpdfstring{Proof of Lemma~\ref{lem:global_lower_bound}}{Proof of the Global Lower Bound Approximation}}\label{AppGlobalLowerBound}
First, let $\mu\boldsymbol I_N\succeq\boldsymbol M\succeq\nabla^2f(\boldsymbol x)$ for all $\boldsymbol x$.
By applying the generalized form of Lemma~12 in \cite{Sun2017MM}, we have
\begin{equation}\label{eq:lemma_quadratic_upper}
f(\boldsymbol x)
\le{} f(\boldsymbol y)+\nabla f(\boldsymbol y)^T(\boldsymbol x-\boldsymbol y)+\frac{1}{2}(\boldsymbol x-\boldsymbol y)^T\boldsymbol M(\boldsymbol x-\boldsymbol y).
\end{equation}
Then, the above inequality can be rewritten as
\begin{equation}\label{eq:lemma_matrix_lower}
f_2(\boldsymbol x)
\ge{} f_2(\boldsymbol y)+\nabla f_2(\boldsymbol y)^T(\boldsymbol x-\boldsymbol y)-\frac{1}{2}(\boldsymbol x-\boldsymbol y)^T\boldsymbol M(\boldsymbol x-\boldsymbol y),
\end{equation}
where $\boldsymbol M\succeq-\nabla^2f_2(\boldsymbol x)$.
As $\mu\boldsymbol I_N\succeq\boldsymbol M$, we have
\begin{equation}\label{eq:lemma_scalar_lower}
f_2(\boldsymbol x)
\ge{} f_2(\boldsymbol y)+\nabla f_2(\boldsymbol y)^T(\boldsymbol x-\boldsymbol y)-\frac{1}{2}\mu(\boldsymbol x-\boldsymbol y)^T(\boldsymbol x-\boldsymbol y).
\end{equation}
This completes the proof.
\section{Derivation of the Hessian Bounds}\label{AppSINR_a}
The function $a_k(\boldsymbol{x})$ defined in \eqref{eq:ak_position_def} can be rewritten as
\begin{equation}
a_k(\boldsymbol{x}) = 2 \sum_{m\in\mathcal{M}} \sum_{\ell=1}^{L_k} \zeta_{a,k}^{m,\ell} \cos(\kappa_{a,k}^{m,\ell}),
\end{equation}
where $\rho_k^\ell \triangleq \cos(\theta_k^\ell)$, $\kappa_{a,k}^{m,\ell} \triangleq \frac{2\pi}{\lambda}\chi_{k}^{\ell}(x_m)+\angle\alpha_k^*+\angle\beta_k^\ell+\angle w_k^m$, and $\zeta_{a,k}^{m,\ell} \triangleq |\alpha_k^*||\beta_k^\ell||w_k^m|$. Then, we have
\begin{equation}
\begin{aligned}
  &\frac{\partial a_k(\boldsymbol{x})}{\partial x_m} = -\frac{4\pi}{\lambda} \sum_{\ell=1}^{L_k} \zeta_{a,k}^{m,\ell} \rho_k^\ell \sin(\kappa_{a,k}^{m,\ell}),
  &\frac{\partial^2 a_k(\boldsymbol{x})}{\partial x_m\partial x_n} = 0,\quad m\ne n,
  &\frac{\partial^2 a_k(\boldsymbol{x})}{\partial x_m^2} = -\frac{8\pi^2}{\lambda^2} \sum_{\ell=1}^{L_k} \zeta_{a,k}^{m,\ell} (\rho_k^\ell)^2 \cos(\kappa_{a,k}^{m,\ell}).
\end{aligned}
\end{equation}
Using
$\left|\cos(\kappa_{a,k}^{m,\ell})\right|\!\leq\! 1$ and
$\left|w_k^m\right| \!\leq\! \max_{n\in\mathcal{M}}\left|w_k^n\right|$
, we have
\begin{equation}
\begin{aligned}
\left|\!
\frac{\partial^2 a_k(\boldsymbol{x})}{\partial x_m^2}
\!\right|\!
\!\leq\!
\frac{8\pi^2\!\left|\alpha_k^*\right|\!
}{\lambda^2}
\!\sum_{\ell=1}^{L_k}
\!\left|\beta_k^\ell\right|\!(\rho_k^\ell)^2
\!\max_{n\in\mathcal{M}}\!\left|w_k^n\right|\!
\triangleq\!
\varpi_{a,k},
\end{aligned}
\end{equation}
which implies $\|\nabla^2 a_k(\boldsymbol x)\|_2\le\varpi_{a,k}$.
Following the same approach as for $a_k(\boldsymbol x)$ and using
Theorem~8.1.18 in \cite{HornJohnson}, we further obtain the Hessian bounds
for $b_k(\boldsymbol x)$ and $\varkappa_q(\boldsymbol x)$ as
\begin{equation}
\varpi_{b,k}
=
\frac{16\pi^2 M|\alpha_k|^2}{\lambda^2}
\sum_{\ell=1}^{L_k}\sum_{p=1}^{L_k}|\beta_k^\ell||\beta_k^p|\max_{m,n\in\mathcal{M}}|[\boldsymbol\Xi_k]_{m,n}|,
\end{equation}
where $\|\nabla^2b_k(\boldsymbol x)\|_2\le\max_{m\in\mathcal M}\sum_{n\in\mathcal M}|[\nabla^2b_k(\boldsymbol x)]_{m,n}|\le\varpi_{b,k}$, which also implies $\varpi_{b,k}\boldsymbol{I}_M \succeq \nabla_{\boldsymbol{x}}^2 b_k(\boldsymbol{x})$.
\begin{equation}
\varpi_{\varkappa,q}
=
\frac{16\pi^2 (M-1)}{\lambda^2}\max_{m,n\in\mathcal{M}}|[\bm\Xi]_{m,n}||\beta_q|^2,
\end{equation}
where 
$\varpi_{\varkappa,q}\boldsymbol{I}_M
\succeq
\nabla_{\boldsymbol{x}}^2 \varkappa_q(\boldsymbol{x})$.
\section{\texorpdfstring{Derivation of the Upper Bound in \eqref{eq:mu_upper_two_part_app}}{Derivation of the Covertness Cross Term Upper Bound}}\label{AppCovertSCA}
The cross term $\mu_q(\boldsymbol x,\bm\delta_q)$ in
\eqref{eq:covert_constraint_expanded_position} can be rewritten as
\begin{equation}\label{eq:mu_row_expansion_app}
\mu_q(\boldsymbol{x},\bm\delta_q)
=\sum_{m\in\mathcal{M}}
\left(
\boldsymbol p_{q,m}(x_m)\bm\delta_q
+\bm\delta_q^H\boldsymbol p_{q,m}^H(x_m)
\right),
\end{equation}
where $\boldsymbol p_{q,m}(x_m)\triangleq
\beta_q e^{\jmath\frac{2\pi}{\lambda}\chi_q(x_m)}[\bm\Xi]_{m,:}$
and $[\bm\Xi]_{m,:}$ denotes the $m$-th row of $\bm\Xi$.
The $m$-th element of $\nabla_{\boldsymbol{x}}\mu_q(\boldsymbol{x},\bm\delta_q)$ can be expressed as
\begin{equation}\label{eq:mu_gradient_entry_app}
\frac{\partial \mu_q(\boldsymbol{x},\bm\delta_q)}{\partial x_m}
=
\boldsymbol r_{q,m}(x_m)\bm\delta_q
+
\bm\delta_q^H\boldsymbol r_{q,m}^H(x_m),
\end{equation}
where $\boldsymbol r_{q,m}(x_m)
\triangleq
\jmath \frac{2\pi}{\lambda} \rho_q \boldsymbol p_{q,m}(x_m)$
and $\rho_q = \cos(\theta_q)$.
Then, we have
\begin{equation}
\begin{aligned}
\frac{\partial^2 \mu_q(\boldsymbol{x},\bm\delta_q)}{\partial x_m^2}
&\!=\!-\frac{4\pi^2\rho_q^2}{\lambda^2}
\bigl(
\boldsymbol p_{q,m}(x_m)\bm\delta_q \!+\!\bm\delta_q^H\boldsymbol p_{q,m}^H(x_m)
\bigr),
\frac{\partial^2 \mu_q(\boldsymbol{x},\bm\delta_q)}
{\partial x_m\partial x_n}
&\!=\!0,\quad m\ne n.
\end{aligned}
\end{equation}
By applying the triangle and Cauchy--Schwarz inequalities and using
$\|\bm\delta_q\|_2 \!\leq\! e_q$ and $\left\|[\bm\Xi]_{m,:}\right\|_2 \!\leq\!\max_{n\in\mathcal{M}} \left\|[\bm\Xi]_{n,:}\right\|_2 $, we have
\begin{equation}
\left|
\frac{\partial^2 \mu_q(\boldsymbol{x},\bm\delta_q)}{\partial x_m^2}
\right|
\le
\frac{8\pi^2}{\lambda^2}\rho_q^2|\beta_q|e_q
\max_{m\in\mathcal{M}}
\left\|
[\bm\Xi]_{m,:}
\right\|_2 \triangleq \varpi_{\mu,q},
\end{equation}
where
$ \varpi_{\mu,q}\mathbf{I}_M
\succeq
\nabla_{\boldsymbol{x}}^2\mu_q(\boldsymbol{x},\bm\delta_q) $.
\section{\texorpdfstring{Proof of Proposition~\ref{prop:bcd_wc_monotonicity}}{Proof of Proposition 1}}\label{AppBCDWC}
Let $F$ and $\overline F$ denote the weighted max-min SINRs of the rank-one and relaxed solutions, respectively. First, in steps~2--4 of Algorithm~\ref{alg:robust_bcd}, for given $\boldsymbol x^{(r)}$, the covariances are optimized and rank-one solutions are recovered.
Secondly, in steps~5--6, for given $\{\boldsymbol w_k^{(r+1)}\}$ and $\boldsymbol R_{\rm A}^{(r+1)}$, the antenna positions are updated by SCA. Combining these two steps, we have~\cite{HaoFluidISAC2025}
\begin{equation}\label{eq:bcd_wc_outer_monotonicity}
\begin{aligned}
F\bigl(\boldsymbol w_k^{(r)},\boldsymbol R_{\rm A}^{(r)},\boldsymbol x^{(r)}\bigr)
&\!\overset{(a)}{\le}\!
\overline F\bigl(\overline{\boldsymbol W}_k^{(r+1)},\overline{\boldsymbol R}^{(r+1)},\boldsymbol x^{(r)}\bigr)
&\!\overset{(b)}{=}\!
F\bigl(\boldsymbol w_k^{(r+1)},\boldsymbol R_{\rm A}^{(r+1)},\boldsymbol x^{(r)}\bigr)
&\!\overset{(c)}{\le}\!
F\bigl(\boldsymbol w_k^{(r+1)},\boldsymbol R_{\rm A}^{(r+1)},\boldsymbol x^{(r+1)}\bigr),
\end{aligned}
\end{equation}
where (a) follows from initializing bisection for \eqref{p2} with the current feasible lower bound, and (b) holds because the rank-one recovery in \eqref{SDR_optimal} preserves each user's SINR at $\boldsymbol x^{(r)}$, as proved in Appendix~\ref{AppSDR}. For (c), \eqref{eq:alpha_update_position} ensures tight SINR lower bounds at each SCA iteration. The optimal value of \eqref{p3_sca} lies between the current and updated $F$. Both sequences are non-decreasing and bounded above by \eqref{Const_3}--\eqref{Const_5}. Thus, the convergence of Algorithm~\ref{alg:robust_bcd} can be guaranteed.
